--
-- Table structure for table `Entregables_PDF`
--

DROP TABLE IF EXISTS `Entregables_PDF`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Entregables_PDF` (
  `entregable_id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL COMMENT 'Nombre descriptivo de la plantilla (ej: "Certificado Proyecto y Dirección")',
  `codigo` varchar(50) NOT NULL COMMENT 'Código único para resolver plantilla (ej: "basico-proyecto-direccion")',
  `descripcion` text COMMENT 'Descripción detallada del entregable',
  `version` varchar(20) NOT NULL DEFAULT '1.0.0' COMMENT 'Versión semántica (MAJOR.MINOR.PATCH)',
  `baja_fecha` datetime DEFAULT NULL COMMENT 'Fecha de baja de la versión, NULL = versión actual en uso',
  `html_template` longtext NOT NULL COMMENT 'HTML con placeholders (ej: {{formData.nombreProyecto}})',
  `css_styles` longtext COMMENT 'CSS específico de la plantilla (inline o <style>)',
  `pdf_config` json DEFAULT NULL COMMENT 'Configuración Puppeteer: { format, margin, orientation, etc. }',
  `template_engine` enum('handlebars','mustache','literal') DEFAULT 'handlebars' COMMENT 'Motor de templating usado',
  `placeholders` json DEFAULT NULL COMMENT 'Lista de placeholders esperados con tipo y descripción',
  `assets` json DEFAULT NULL COMMENT 'Imágenes/logos en base64 o URLs absolutas: { "logo": "data:image/svg+xml;base64,..." }',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `user_id` int DEFAULT NULL COMMENT 'Usuario que creó la plantilla',
  PRIMARY KEY (`entregable_id`),
  UNIQUE KEY `codigo` (`codigo`),
  KEY `idx_codigo` (`codigo`),
  KEY `idx_baja_fecha` (`baja_fecha`),
  KEY `idx_template_engine` (`template_engine`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `Entregables_PDF_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `Usuarios` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Plantillas HTML/CSS para generar entregables PDF con Puppeteer';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `Entregables_PDF`
--

LOCK TABLES `Entregables_PDF` WRITE;
/*!40000 ALTER TABLE `Entregables_PDF` DISABLE KEYS */;
INSERT INTO `Entregables_PDF` VALUES (1,'Certificado Proyecto y Dirección','basico-proyecto-direccion','Plantilla HTML completa para certificado PDF de honorarios profesionales - Cálculo Proyecto y Dirección de Obras de Arquitectura. Motor: Handlebars. Páginas: 2 (datos + notas institucionales CPAU)','1.0',NULL,'<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Certificado de Honorarios CPAU - {{calculationNumber}}</title>\n  \n  <style>\n    /* ============================================================\n       ESTILOS BASE\n       ============================================================ */\n\n      /* --- 1. AVENIR ROMAN --- */\n    @font-face {\n      font-family: \'Avenir\';\n      src: url(\'Avenir_Roman.ttf\') format(\'truetype\'); /* Ver nombre archivo */\n      font-weight: 400; /* Peso medio */\n      font-style: normal;\n      font-display: swap;\n    }\n    \n    /* --- AVENIR NORMAL ( por defecto) --- */\n    @font-face {\n      font-family: \'Avenir\';\n      src: url(\'Avenir.ttf\') format(\'truetype\'); /* Ver nombre archivo */\n      font-weight: 500; /* Peso medio */\n      font-style: normal;\n      font-display: swap;\n    }\n\n    /* --- AVENIR BLACK --- */\n    @font-face {\n      font-family: \'Avenir\';\n      src: url(\'Avenir_Black.ttf\') format(\'truetype\'); /* Ver nombre archivo */\n      font-weight: 900;\n      font-style: normal;\n      font-display: swap;\n    }\n\n    * {\n      margin: 0;\n      padding: 0;\n      box-sizing: border-box;\n    }\n\n    :root {\n      --blue-color:lab(34.931% 12.316% -35.555%);\n      --cyan-color:lab(80.379% -14.217% -11.292%);\n\n      --border-title-gray-color: lab(42.056% 0.326% 0.117%);\n      --border-blue-color:lab(34.931% 12.316% -35.555%);\n      --border-gray-color:lab(43.192% 0% 0%);\n      \n      --text-black-color:lab(10.709% -0.294% 1.107%);\n      --text-gray-color:lab(42.056% 0.326% 0.117%);\n      --text-white-color:lab(100% 0% 0%);\n      --text-blue-color:lab(34.931% 12.316% -35.555%);\n      \n      --bottom-color:lab(41.94%, -0.123%, 0.456%);\n    }\n    \n    body {\n      font-family: \'Avenir\', \'Segoe UI\', sans-serif;\n      font-size: 10pt;\n      line-height: 1.3;  /* ← TICKET-003: Reducido de 1.4 a 1.3 */\n      font-weight: 400;\n      background: var(--text-white-color);\n    }\n\n    /* --- Títulos (Cargará Avenir Black) --- */\n    h1, h2, h3, h4, strong, .resumen-label, .section-title, .header-title {\n      font-family: \'Avenir\', \'Segoe UI\', sans-serif;\n      font-weight: 900;\n    }\n    \n    /* ============================================================\n       PaGINA (A4)\n       ============================================================ */\n    .page {\n      width: 210mm;\n      min-height: 255mm;  /* ← AJUSTADO: 297mm - 35mm (márgenes Puppeteer) - 7mm (margen seguridad) */\n      padding: 0 0 5mm 0;  /* ← TICKET-003: Agregar 5mm padding bottom para separación del footer */\n      page-break-after: always;\n      page-break-inside: avoid;\n      background: var(--text-white-color);\n    }\n\n    .page:last-child {\n      page-break-after: auto;\n    }\n    \n    /* Evitar cortes de pagina en elementos */\n    table, .section-title, .resumen-item, .certificate-header, .disclaimer {\n      page-break-inside: avoid;\n    }\n    \n    thead {\n      display: table-header-group;\n    }\n    \n    tr {\n      page-break-inside: avoid;\n    }\n    \n    /* ============================================================\n       HEADER DEL CERTIFICADO\n       ============================================================ */\n    .certificate-header {\n      display: flex;\n      align-items: stretch;\n      gap: 15px;\n      margin-bottom: 20px;  /* ← TICKET-003: Reducido de 25px a 20px */\n    }\n    \n    .header-left {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      width: 140px;\n      background: var(--blue-color);\n      border-radius: 8px;\n      padding: 15px;\n      flex-shrink: 0;\n    }\n    \n    .logo {\n      width: 100px;\n      height: auto;\n    }\n    \n    .header-right {\n      flex: 1;\n      padding: 15px 20px;\n      background: var(--cyan-color);\n      border-radius: 8px;\n      display: flex;\n      flex-direction: column;\n      justify-content: center;\n    }\n    \n    .header-title {\n      position: relative;\n      font-size: 25px;\n      font-weight: 600;\n      padding-bottom: 8px;\n      margin-bottom: 8px;\n      letter-spacing: 0.5px;\n      color: var(--text-black-color);\n    }\n\n    .header-title::after\n    {\n      content: \"\";\n      position: absolute;\n      height: 1px;\n      left: 0;\n      bottom: 0;\n      width: 100%;\n      background-color: var(--border-title-gray-color);  /* Línea flotante sutil */\n    }\n    \n    .header-metadata {\n      font-size: 9pt;\n      display: flex;\n      justify-content: space-between;\n      color: var(--text-black-color);\n    }\n    \n    .metadata-item {\n      display: inline-block;\n    }\n\n    .metadata-item span { font-weight: 500; }\n    \n    .metadata-label {\n      font-weight: 500;\n    }\n    \n    /* ============================================================\n       RESUMEN DEL PROYECTO\n       ============================================================ */\n    .section-title-sin-linea, .section-title {\n      font-size: 16px;\n      font-weight: 900;\n      color: var(--text-black-color);\n      margin-bottom: 12px;  /* ← TICKET-003: Reducido de 15px a 12px */\n      margin-top: 15px;  /* ← TICKET-003: Reducido de 20px a 15px */\n    }\n\n    .resumen-grid {\n      display: flex;\n      flex-direction: column;\n      gap: 0;\n      margin-bottom: 15px;\n      padding: 0 15px;\n      border: 2px solid var(--border-gray-color);\n      border-radius: 12px;\n      overflow: hidden;\n      background: var(--text-white-color);\n    }\n\n    .resumen-item-container {\n      display: flex;\n      flex-direction: row;\n      border-bottom: 1px solid var(--border-gray-color);\n      padding: 15px 0;\n      gap: 10px;\n    }\n\n    .resumen-item-container:last-child {\n      border-bottom: none;\n    }\n    \n    .resumen-item {\n      display: flex;\n      flex: 1;\n      gap: 5px;\n    }\n    \n    .resumen-item:nth-child(1),\n    .resumen-item:nth-child(2) {\n      /* Fila 1: 2 items de 3 columnas */\n      grid-column: span 3;\n    }\n    \n    .resumen-item:nth-child(3),\n    .resumen-item:nth-child(4),\n    .resumen-item:nth-child(5) {\n      /* Fila 2: 3 items de 2 columnas */\n      grid-column: span 2;\n    }\n    \n    .resumen-item:nth-child(6),\n    .resumen-item:nth-child(7) {\n      /* Fila 3: 2 items de 3 columnas */\n      grid-column: span 3;\n      border-bottom: none;\n    }\n    \n    .resumen-label {\n      font-weight: 900;\n      color: var(--text-gray-color);\n      white-space: nowrap;\n    }\n    \n    .resumen-value {\n      color: var(--text-gray-color);\n    }\n    \n    /* ============================================================\n       DISCLAIMER/IMPORTANTE\n       ============================================================ */\n    .disclaimer {\n      \n      border: 1px solid var(--blue-color);\n      border-radius: 12px;\n      padding: 12px;  /* ← TICKET-003: Reducido de 15px a 12px */\n      padding-right: 40px;\n      margin: 15px 0;  /* ← TICKET-003: Reducido de 20px a 15px */\n    }\n    \n    .disclaimer-title {\n      font-size: 12pt;\n      font-weight: 900;\n    }\n    \n    .disclaimer-text {\n      font-size: 9.5pt;\n      line-height: 1.4;  /* ← TICKET-003: Reducido de 1.6 a 1.4 */\n      color: var(--text-black-color);\n    }\n    /* ============================================================\n       TABLAS DE HONORARIOS\n       ============================================================ */\n    table {\n      border-collapse: separate;\n      border-spacing: 0;\n      margin-bottom: 15px;  /* ← TICKET-003: Reducido de 20px a 15px */\n      padding: 0 15px;  /* Padding horizontal para efecto de líneas flotantes */\n      font-size: 10pt;  /* ← TICKET-003: Reducido de 9pt a 8.5pt */\n      background: var(--text-white-color);\n      border: 2px solid var(--border-gray-color);\n      border-radius: 12px;\n      overflow: hidden;\n\n      table-layout: fixed;\n\n      margin-right: 1px;\n    }\n\n    table:last-child {\n      margin-bottom: 0;\n    }\n\n    table, .resumen-grid, .disclaimer\n    {\n      width: calc(100% - 3px);\n    }\n    \n    thead th {\n      font-size: 9pt;\n      padding: 15px 0;  /* ← TICKET-003: Reducido de 10px a 8px */\n      text-align: left;\n      border-bottom: 1px solid var(--border-gray-color);\n      font-weight: 900;\n      color: var(--text-gray-color);\n    }\n    \n    /* Anchos específicos para cada columna (solo tablas de honorarios) */\n    table:not(.etapas-table) thead th:nth-child(1),\n    table:not(.etapas-table) tbody td:nth-child(1) {\n      width: 5%;\n      text-align: left;\n    }\n\n    table:not(.etapas-table) thead th:nth-child(2),\n    table:not(.etapas-table) tbody td:nth-child(2) {\n      width: 45%;\n    }\n    \n    table:not(.etapas-table) thead th:nth-child(3),\n    table:not(.etapas-table) tbody td:nth-child(3) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table:not(.etapas-table) thead th:nth-child(4),\n    table:not(.etapas-table) tbody td:nth-child(4) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table:not(.etapas-table) thead th:nth-child(5),\n    table:not(.etapas-table) tbody td:nth-child(5) {\n      width: 20%;\n      text-align: left;\n    }\n    \n    \n     /* Anchos específicos para cada columna - Subtotales */\n    table tr.subtotal-row td:nth-child(1) {\n      width: 50%;\n      text-align: left;\n    }\n\n    table tr.subtotal-row td:nth-child(2) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table tr.subtotal-row td:nth-child(3) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table tr.subtotal-row td:nth-child(4) {\n      width: 20%;\n      text-align: left;\n    }\n\n    /* Anchos específicos para cada columna - Totales */\n    table tr.total-row td:nth-child(1) {\n      width: 50%;\n      text-align: left;\n    }\n\n    table tr.total-row td:nth-child(2) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table tr.total-row td:nth-child(3) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table tr.total-row td:nth-child(4) {\n      width: 20%;\n      text-align: left;\n    }\n\n    /*\n    thead th:first-child {\n      border-top-left-radius: 12px;\n    }\n    \n    thead th:last-child {\n      border-top-right-radius: 12px;\n    }*/\n    \n    tbody td {\n      padding: 15px 0;  /* ← TICKET-003: Reducido de 8px a 6px */\n      border-bottom: 1px solid var(--border-gray-color);\n    }\n    /*\n    tbody tr:last-child td {\n      border-bottom: none;\n    }*/\n    /*\n    tbody tr:last-child td:first-child {\n      border-bottom-left-radius: 12px;\n    }\n    \n    tbody tr:last-child td:last-child {\n      border-bottom-right-radius: 12px;\n    }*/\n    \n    \n    .centered {\n      text-align: center;\n    }\n    \n    .right-align {\n      text-align: right;\n    }\n    \n    .subtotal-row {\n      \n      color: var(--blue-color);\n      font-weight: 900;\n      \n    }\n    \n    .subtotal-row td {\n      padding: 15px 0;  /* Solo padding vertical para efecto flotante */\n      border-bottom: none;\n    }\n    \n    .subtotal-row td:first-child {\n      text-align: left !important;\n      border-bottom-left-radius: 12px;\n    }\n    \n    .subtotal-row td:last-child {\n      text-align: left !important;\n      border-bottom-right-radius: 12px;\n    }\n    \n    .totales-table\n    {\n      border: 2px solid var(--blue-color);\n    }\n\n    .total-row {\n      color: var(--blue-color);\n      font-weight: 900;\n      font-size: 10pt;\n      /*border-bottom: 1px solid var(--blue-color);*/\n    }\n    \n    .total-row:last-child{\n      color: var(--text-black-color);\n    }\n    \n    .total-row td {\n      padding: 12px 0;  /* Solo padding vertical para efecto flotante */\n      border-bottom: 1px solid var(--blue-color);\n    }\n\n    .total-row:last-child td {\n      border-bottom: none;\n    }\n    \n    .total-row td:first-child {\n      text-align: left !important;\n      \n    }\n    \n    .total-row td:last-child {\n      \n      text-align: left !important;\n    }\n    \n    /* Separaci&oacute;n entre secciones de tablas */\n    .table-section {\n      margin-bottom: 10px;\n    }\n    \n    /* ============================================================\n       NOTA FINAL\n       ============================================================ */\n     .nota-final {\n      padding: 0 10px;\n      \n      font-size: 9pt;\n    }\n    \n    /* ============================================================\n       PaGINA 2 - NOTAS\n       ============================================================ */\n    .notas-section {\n      margin-top: 1px;\n    }\n        \n    .nota-block h4 {\n      font-size: 14px;\n      line-height: 1.4;  /* ← TICKET-003: Reducido de 1.6 a 1.4 */\n      font-weight: 900;\n      margin-top: 5px;\n      \n      /* margin-bottom: 8px; */\n    }\n    \n    .nota-block p {\n      font-size: 9.2pt;\n      line-height: 1.2;  /* ← TICKET-003: Reducido de 1.6 a 1.4 */\n      text-align: justify;\n    }\n    \n    .etapas-table {\n      width: auto;\n      min-width: 250px;\n      margin: 10px 0;\n      padding: 0 15px;  /* Padding horizontal para efecto de líneas flotantes */\n      border-collapse: collapse;\n      font-size: 9.2pt;\n      border: none;\n      border-radius: 0;\n    }\n    \n    .etapas-table td {\n      padding: 6px 0;  /* Solo padding vertical para efecto flotante */\n      border-bottom: 1px solid var(--border-gray-color);\n    }\n    .etapas-table tr:last-child td {\n      border-bottom: none;\n    }\n    \n  </style>\n</head>\n<body>\n  <!-- ========================================\n       PaGINA 1: DATOS DEL C&aacute;LCULO\n       ======================================== -->\n  <div class=\"page\">\n    <!-- Header del Certificado -->\n    <div class=\"certificate-header\">\n      <div class=\"header-left\">\n        <img src=\"{{logoCPAU}}\" alt=\"CPAU Logo\" class=\"logo\" />\n      </div>\n      <div class=\"header-right\">\n        <div class=\"header-title\">C&aacute;lculo de honorarios profesionales sugeridos</div>\n        <div class=\"header-metadata\">\n          <div class=\"metadata-item\">\n            <span class=\"metadata-label\">Tipo:</span>\n            <span>{{tipoNombre}}</span>\n          </div>\n          <div class=\"metadata-item\">\n            <span class=\"metadata-label\">Fecha:</span>\n            <span>{{currentDate}}</span>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Disclaimer Legal -->\n    <div class=\"disclaimer-container\">\n      <p class=\"disclaimer-text\">\n        Este c&aacute;lculo es una <strong>estimaci&oacute;n de referencia</strong> basada en los datos proporcionados \n        y factores est&aacute;ndar del mercado. Los valores finales pueden variar seg&uacute;n condiciones particulares \n        de cada proyecto. <strong>No constituye una cotizaci&oacute;n formal ni un compromiso contractual.</strong>\n        <br />\n        <br />\n        {{{vigenciaFE}}}\n        </p>\n    </div>\n\n\n    <!-- Resumen del Proyecto -->\n    <h4 class=\"section-title\">Resumen del Proyecto - Informaci&oacute;n ingresada por el/la profesional</h4>\n    <div class=\"resumen-grid\">\n      <!-- Fila 1: Nombre del Proyecto | Comitente -->\n      <div class=\"resumen-item-container\">\n\n        <div class=\"resumen-item\">\n          <span class=\"resumen-label\">Nombre del Proyecto:</span>\n          <span class=\"resumen-value\">{{nombreProyecto}}</span>\n        </div>\n        <div class=\"resumen-item\">\n          <span class=\"resumen-label\">Comitente:</span>\n          <span class=\"resumen-value\">{{cliente}}</span>\n        </div>\n       \n      </div>\n      <!-- Fila 2: Tipo de obra | Destino/Uso -->\n      <div class=\"resumen-item-container\">\n        <div class=\"resumen-item\">\n          <span class=\"resumen-label\">Tipo de obra:</span>\n          <span class=\"resumen-value\">{{tipoObra}}</span>\n        </div>\n        <div class=\"resumen-item\">\n          <span class=\"resumen-label\">Destino/Uso:</span>\n          <span class=\"resumen-value\">{{destinoUso}}</span>\n        </div> \n      </div>\n\n      <!-- Fila 3: Superficie total | Costo por metro cuadrado -->\n      <div class=\"resumen-item-container\">\n        <div class=\"resumen-item\">\n          <span class=\"resumen-label\">Superficie total:</span>\n          <span class=\"resumen-value\">{{superficieTotal}} m²</span>\n        </div>\n        <div class=\"resumen-item\">\n          <span class=\"resumen-label\">Costo por metro cuadrado:</span>\n          <span class=\"resumen-value\">{{valorMetro2ARS}}</span>\n        </div> \n      </div>\n\n      <!-- Fila 4: Costo estimado por obra (ARS) | Costo estimado por obra (USD) -->\n      <div class=\"resumen-item-container\">\n       <div class=\"resumen-item\">\n          <span class=\"resumen-label\">Costo estimado de obra (ARS):</span>\n          <span class=\"resumen-value\">{{valorObraARS}}</span>\n        </div>\n        <div class=\"resumen-item\">\n          <span class=\"resumen-label\">Costo estimado de obra (USD):</span>\n          <span class=\"resumen-value\">{{valorObraUSD}}</span>\n        </div>\n      </div>\n\n      <!-- Fila 4: Plazo de ejecucion de las tareas encomendadas -->\n      <div class=\"resumen-item-container\">\n        <div class=\"resumen-item\">\n          <span class=\"resumen-label\">Plazo de ejecuci&oacute;n de las tareas encomendadas:</span>\n          <span class=\"resumen-value\"></span>\n        </div>\n      </div>\n    </div>\n\n    <!-- Detalle de Honorarios -->\n    <h4 class=\"section-title-sin-linea\">Detalle de honorarios</h4>\n\n    <!-- SECCIoN: Honorarios Obra -->\n    {{#if honorariosObra}}\n    <div class=\"table-section\">\n      <table>\n        <!-- Encabezado: siempre se muestra en la primera seccion -->\n        <thead>\n          <tr>\n            <th class=\"centered\">&Iacute;tem</th>\n            <th>Tarea Profesional</th>\n            <th class=\"right-align\">Importe ARS</th>\n            <th class=\"right-align\">Importe USD</th>\n            <th class=\"centered\">% sobre costo de obra</th>\n          </tr>\n        </thead>\n        <tbody>\n          {{#each honorariosObra}}\n          <tr>\n            <td class=\"centered\">{{this.indice}}</td>\n            <td>\n            \n              {{this.tareaProfesional}}\n            </td>\n            <td class=\"right-align\">{{this.importeARS}}</td>\n            <td class=\"right-align\">{{this.importeUSD}}</td>\n            <td class=\"centered\">{{this.porcentaje}}%</td>\n          </tr>\n          {{/each}}\n          \n          <!-- Subtotal Obra -->\n          <tr class=\"subtotal-row\">\n            <td colspan=\"2\"><strong>Total honorarios obra</strong></td>\n            <td class=\"right-align\"><strong>{{subtotalObraARS}}</strong></td>\n            <td class=\"right-align\"><strong>{{subtotalObraUSD}}</strong></td>\n            <td class=\"centered\"><strong>{{subtotalObraPorcentaje}}%</strong></td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n    {{/if}}\n\n    <!-- SECCIoN: Honorarios Adicionales -->\n    {{#if honorariosAdicionales}}\n    <div class=\"table-section\">\n      <table>\n        <!-- Encabezado: solo si NO existe honorariosObra -->\n        {{#unless honorariosObra}}\n        <thead>\n          <tr>\n            <th class=\"centered\">&Iacute;tem</th>\n            <th>Tarea Profesional</th>\n            <th class=\"right-align\">Importe ARS</th>\n            <th class=\"right-align\">Importe USD</th>\n            <th class=\"centered\">% sobre costo de obra</th>\n          </tr>\n        </thead>\n        {{/unless}}\n        <tbody>\n          {{#each honorariosAdicionales}}\n          <tr>\n            <td class=\"centered\">{{this.indice}}</td>\n            <td>\n              {{this.tareaProfesional}}\n            </td>\n            <td class=\"right-align\">{{this.importeARS}}</td>\n            <td class=\"right-align\">{{this.importeUSD}}</td>\n            <td class=\"centered\">{{this.porcentaje}}%</td>\n          </tr>\n          {{/each}}\n          \n          <!-- Subtotal Adicionales -->\n          <tr class=\"subtotal-row\">\n            <td colspan=\"2\"><strong>Total honorarios adicionales</strong></td>\n            <td class=\"right-align\"><strong>{{subtotalAdicionalesARS}}</strong></td>\n            <td class=\"right-align\"><strong>{{subtotalAdicionalesUSD}}</strong></td>\n            <td class=\"centered\"><strong>{{subtotalAdicionalesPorcentaje}}%</strong></td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n    {{/if}}\n\n    <!-- SECCIoN: Honorarios Especialidades -->\n    {{#if honorariosEspecialidades}}\n    <div class=\"table-section\">\n      <table>\n        <!-- Encabezado: solo si NO existe honorariosObra NI honorariosAdicionales -->\n        {{#unless honorariosObra}}\n          {{#unless honorariosAdicionales}}\n          <thead>\n            <tr>\n              <th class=\"centered\">&Iacute;tem</th>\n              <th>Tarea Profesional</th>\n              <th class=\"right-align\">Importe ARS</th>\n              <th class=\"right-align\">Importe USD</th>\n              <th class=\"centered\">% sobre costo de obra</th>\n            </tr>\n          </thead>\n          {{/unless}}\n        {{/unless}}\n        <tbody>\n          {{#each honorariosEspecialidades}}\n          <tr>\n            <td class=\"centered\">{{this.indice}}</td>\n            <td>\n              {{this.tareaProfesional}}\n            </td>\n            <td class=\"right-align\">{{this.importeARS}}</td>\n            <td class=\"right-align\">{{this.importeUSD}}</td>\n            <td class=\"centered\">{{this.porcentaje}}%</td>\n          </tr>\n          {{/each}}\n          \n          <!-- Subtotal Especialidades -->\n          <tr class=\"subtotal-row\">\n            <td colspan=\"2\"><strong>Total honorarios especialidades</strong></td>\n            <td class=\"right-align\"><strong>{{subtotalEspecialidadesARS}}</strong></td>\n            <td class=\"right-align\"><strong>{{subtotalEspecialidadesUSD}}</strong></td>\n            <td class=\"centered\"><strong>{{subtotalEspecialidadesPorcentaje}}%</strong></td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n    {{/if}}\n\n    <!-- TOTAL GENERAL -->\n    <div class=\"table-section\">\n      <table class=\"totales-table\">\n        <tbody>\n          <tr class=\"total-row\">\n            <td colspan=\"2\"><strong>TOTAL GENERAL</strong></td>\n            <td class=\"right-align\"><strong>{{totalGeneralARS}}</strong></td>\n            <td class=\"right-align\"><strong>{{totalGeneralUSD}}</strong></td>\n            <td class=\"centered\"><strong>{{totalGeneralPorcentaje}}%</strong></td>\n          </tr>\n          <tr class=\"total-row\">\n            <td colspan=\"3\"><strong>Plazo estimado de ejecuci&oacute;n: {{plazoEjecucion}} meses</strong></td>\n            <td class=\"right-align\"></td>\n            <td class=\"centered\"></td>\n\n            <!-- <td colspan=\"5\"><strong>Plazo estimado de ejecuci&oacute;n: {{plazoEjecucion}} meses</strong></td> -->\n          </tr>\n        </tbody>\n      </table>\n    </div>\n\n    <!-- Nota Final -->\n    <div class=\"nota-final\">\n      <p>NOTA: Este honorario corresponde &uacute;nicamente a las tareas profesionales seleccionadas. NO incluye IVA.</p>\n    </div>\n  </div>\n  <!-- Fin pagina 1 -->\n\n  <!-- ========================================\n       PÁGINA 2: NOTAS\n       ======================================== -->\n  <div class=\"page\">\n    <!-- Header (repetido para PDF) -->\n    <div class=\"certificate-header\">\n      <div class=\"header-left\">\n        <img src=\"{{logoCPAU}}\" alt=\"CPAU Logo\" class=\"logo\" />\n      </div>\n      <div class=\"header-right\">\n        <div class=\"header-title\">C&aacute;lculo de honorarios profesionales sugeridos</div>\n        <div class=\"header-metadata\">\n          <div class=\"metadata-item\">\n            <span class=\"metadata-label\">Tipo:</span>\n            <span>{{tipoNombre}}</span>\n          </div>\n          <div class=\"metadata-item\">\n            <span class=\"metadata-label\">Fecha:</span>\n            <span>{{currentDate}}</span>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Contenido de Notas -->\n    <div class=\"notas-section\">\n      <h2 class=\"section-title-sin-linea\">Notas</h2>\n      \n      <!-- Alcance y car&aacute;cter del c&aacute;lculo -->\n      <section class=\"nota-block\">\n        <h4>Alcance y car&aacute;cter del c&aacute;lculo</h4>\n        <p>Los c&aacute;lculos de honorarios profesionales que resultan del uso de esta calculadora tienen como finalidad orientar a las partes en los acuerdos de honorarios por las distintas tareas que los arquitectos llevan adelante.</p>\n        <p>El monto de honorarios se determina a partir de las variables ingresadas por el profesional (tipo de obra, superficie, costo estimado por m2, alcance del encargo y otros) y los porcentajes de honorarios sugeridos por el CPAU. El objetivo de este c&aacute;lculo es obtener un honorario equitativo.</p>\n        <p>El modo de pago, as&iacute; como el sistema de ajuste de los valores ser&aacute; el que acuerden las partes. Todo cambio en el alcance de las tareas profesionales encomendadas, as&iacute; como cualquiera de las variables ingresadas para el c&aacute;lculo deber&aacute; reflejarse en los honorarios.</p>\n      </section>\n\n      <!-- Costo de obra considerado -->\n      <section class=\"nota-block\">\n        <h4>Costo de obra considerado</h4>\n        <p>El costo de obra por m2 a ser utilizado en el c&aacute;lculo debe ser consecuencia de una estimaci&oacute;n consensuada entre profesional y comitente.</p><p>El CPAU publica mensualmente &iacute;ndices de referencia de costos de construcci&oacute;n, elaborados por distintos organismos y/o medios, disponibles en la web institucional, quedando a criterio del/la profesional y del comitente el uso de alguno de ellos o arribar a un acuerdo diferente.</p>\n      </section>\n\n      <!-- Etapas del proyecto -->\n      <section class=\"nota-block\">\n        <h4>Etapas de proyecto y direcci&oacute;n de obra</h4>\n        <table class=\"etapas-table\">\n          <tbody>\n            <tr><td>Croquis preliminar</td><td>10%</td></tr>\n            <tr><td>Anteproyecto</td><td>15%</td></tr>\n            <tr><td>Proyecto b&aacute;sico</td><td>15%</td></tr>\n            <tr><td>Documentaci&oacute;n licitatoria</td><td>20%</td></tr>\n            <tr><td>Total proyecto</td><td>60%</td></tr>\n            <tr><td>Direcci&oacute;n de obra</td><td>40%</td></tr>\n          </tbody>\n        </table>\n      </section>\n\n      <!-- Texto - documentacion -->\n      <section class=\"nota-block\">\n        <p>La documentaci&oacute;n ejecutiva es complementaria de la documentaci&oacute;n licitatoria y comprende el desarrollo de procedimientos constructivos, la elaboraci&oacute;n de planos de taller, despieces para la fabricaci&oacute;n y montaje de elementos, y planos, c&aacute;lculos y detalles sobre procesos t&eacute;cnicos de construcci&oacute;n. Su contenido, alcance y necesidad de elaboraci&oacute;n de dicha documentaci&oacute;n depender&aacute;n de caracter&iacute;sticas del proyecto y ser&aacute;n definidos de com&uacute;n acuerdo entre el Comitente y el Profesional. Estas tareas se consideran adicionales a las etapas de proyecto anteriormente mencionadas.</p>\n      </section>\n\n      <section class=\"nota-block\">\n        <h4></h4>\n        <p>La supervisi&oacute;n de la obra es una tarea de acompa&ntilde;amiento para la fiel interpretaci&oacute;n del proyecto por parte de la Direcci&oacute;n de obra.</p>\n        <p>No incluye firma profesional ni tareas ejecutivas, y no reemplaza la obligatoriedad de un Director/a de obra.</p>\n        <p>A fin de conocer el contenido y alcance de cada una de las etapas del proyecto, se recomienda consultar el MEPAU.</p>\n      </section>\n\n      <!-- Alcance de los honorarios sugeridos -->\n      <section class=\"nota-block\">\n        <h4>Alcance de los honorarios sugeridos</h4>\n        <p>Los honorarios resultantes de este c&aacute;lculo contemplan las tareas profesionales correspondientes a un encargo ordinario, de acuerdo con los alcances definidos por la normativa y usos profesionales vigentes, ver MEPAU A-115.</p>\n        <p>Las tareas que corresponden a una encomienda de proyecto y direcci&oacute;n de obra no comprenden las vinculadas a interiorismo, paisajismo, equipamiento no edilicio, mobiliario, iluminaci&oacute;n, cortinas u otros elementos no habituales en obras ordinarias por lo que en caso de ser encomendadas, los honorarios deberán ser adicionales a los de proyecto y direcci&oacute;n de obra.</p>\n        <p>Se recomienda a los profesionales integrar al contrato el detalle de tareas, la modalidad de prestaci&oacute;n y la lista de documentos entregables, pudiendo indicarse tambi&eacute;n su modo de ejecuci&oacute;n (AutoCAD, BIM), a fin de evitar confusiones. Se sugiere consultar los modelos anexos del MEPAU A-115 Art. 3.7.</p>\n      </section>\n\n      <!-- Conceptos no incluidos -->\n      <section class=\"nota-block\">\n        <h4>Conceptos no incluidos en los honorarios:</h4>\n        <p>IVA, en caso de corresponder.<br />Gesti&oacute;n municipal, derechos de construcci&oacute;n y/o cualquier tipo de grav&aacute;menes, tasas o derechos.<br />C&aacute;lculo estructural, salvo el caso que se encuentre espec&iacute;ficamente agregado al c&aacute;lculo realizado.<br />Proyecto de instalaciones, salvo el caso que se encuentren espec&iacute;ficamente agregados al c&aacute;lculo realizado.<br />Documentaci&oacute;n y planos comerciales, renders, maquetas, etc.<br />Cualquier otro concepto que no est&eacute; expresado en el c&aacute;lculo.</p>\n      </section>\n\n      <!-- Resoluci&oacute;n de los honorarios -->\n      <section class=\"nota-block\">\n        <h4>Resoluci&oacute;n de los honorarios</h4>\n        <p>En caso de que alguna de las partes decida no continuar con la totalidad del encargo, deber&aacute;n abonarse los honorarios de las tareas efectivamente realizadas seg&uacute;n lo acordado por las partes, y considerando las etapas de proyecto previamente mencionadas en este documento.</p>\n        <p>En caso de rescisi&oacute;n unilateral por parte del comitente, se deber&aacute; convenir un resarcimiento en favor del profesional por las tareas encomendadas y no ejecutadas, de acuerdo a la normativa vigente.</p>\n      <p><br></p>\n      <p><br></p>\n        <p>Para ampliar la informaci&oacute;n consultar al MEPAU, cap&iacute;tulo 02 Honorarios, o ponerse en contacto con tecnica@cpau.org</p>\n      </section>\n    </div>\n  </div>\n\n  <!-- Fin pagina 2 -->\n</body>\n</html>','/* CSS embebido en html_template */','{\"format\": \"A4\", \"margin\": {\"top\": \"20mm\", \"left\": \"15mm\", \"right\": \"15mm\", \"bottom\": \"20mm\"}, \"printBackground\": true, \"preferCSSPageSize\": false}','handlebars','{\"formData\": {\"cliente\": \"string\", \"tipoObra\": \"string\", \"valorObra\": \"number\", \"nombreProyecto\": \"string\", \"superficieCubierta\": \"number\", \"superficieSemicubierta\": \"number\"}, \"currentDate\": \"string\", \"calculationNumber\": \"string\", \"calculationResult\": {\"moneda\": \"string\", \"honorarioTotal\": \"number\"}}','{\"logoCPAU\": \"data:image/svg+xml;base64,\"}','2026-06-15 01:53:02','2026-07-23 21:53:26',NULL),(2,'Certificado Otras Tareas','otras-tareas','Plantilla HTML completa para certificado PDF de honorarios profesionales - Cálculo Otras Tareas. Motor: Handlebars. Páginas: 2 (datos + notas institucionales CPAU)','1.0',NULL,'<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Certificado de Honorarios CPAU - {{calculationNumber}}</title>\n  \n  <style>\n    /* ============================================================\n       ESTILOS BASE\n       ============================================================ */\n\n      /* --- 1. AVENIR ROMAN --- */\n    @font-face {\n      font-family: \'Avenir\';\n      src: url(\'Avenir_Roman.ttf\') format(\'truetype\'); /* Ver nombre archivo */\n      font-weight: 400; /* Peso medio */\n      font-style: normal;\n      font-display: swap;\n    }\n    \n    /* --- AVENIR NORMAL ( por defecto) --- */\n    @font-face {\n      font-family: \'Avenir\';\n      src: url(\'Avenir.ttf\') format(\'truetype\'); /* Ver nombre archivo */\n      font-weight: 500; /* Peso medio */\n      font-style: normal;\n      font-display: swap;\n    }\n\n    /* --- AVENIR BLACK --- */\n    @font-face {\n      font-family: \'Avenir\';\n      src: url(\'Avenir_Black.ttf\') format(\'truetype\'); /* Ver nombre archivo */\n      font-weight: 900;\n      font-style: normal;\n      font-display: swap;\n    }\n\n    * {\n      margin: 0;\n      padding: 0;\n      box-sizing: border-box;\n    }\n\n    :root {\n      --blue-color:lab(34.931% 12.316% -35.555%);\n      --cyan-color:lab(80.379% -14.217% -11.292%);\n\n      --border-title-gray-color: lab(42.056% 0.326% 0.117%);\n      --border-blue-color:lab(34.931% 12.316% -35.555%);\n      --border-gray-color:lab(43.192% 0% 0%);\n      \n      --text-black-color:lab(10.709% -0.294% 1.107%);\n      --text-gray-color:lab(42.056% 0.326% 0.117%);\n      --text-white-color:lab(100% 0% 0%);\n      --text-blue-color:lab(34.931% 12.316% -35.555%);\n      \n      --bottom-color:lab(41.94%, -0.123%, 0.456%);\n    }\n    \n    body {\n      font-family: \'Avenir\', \'Segoe UI\', sans-serif;\n      font-size: 10pt;\n      line-height: 1.3;  /* ← TICKET-003: Reducido de 1.4 a 1.3 */\n      font-weight: 400;\n      background: var(--text-white-color);\n    }\n\n    /* --- Títulos (Cargará Avenir Black) --- */\n    h1, h2, h3, h4, strong, .resumen-label, .section-title, .header-title {\n      font-family: \'Avenir\', \'Segoe UI\', sans-serif;\n      font-weight: 900;\n    }\n    \n    /* ============================================================\n       PaGINA (A4)\n       ============================================================ */\n    .page {\n      width: 210mm;\n      min-height: 255mm;  /* ← AJUSTADO: 297mm - 35mm (márgenes Puppeteer) - 7mm (margen seguridad) */\n      padding: 0 0 5mm 0;  /* ← TICKET-003: Agregar 5mm padding bottom para separación del footer */\n      page-break-after: always;\n      page-break-inside: avoid;\n      background: var(--text-white-color);\n    }\n\n    .page:last-child {\n      page-break-after: auto;\n    }\n    \n    /* Evitar cortes de pagina en elementos */\n    table, .section-title, .resumen-item, .certificate-header, .disclaimer {\n      page-break-inside: avoid;\n    }\n    \n    thead {\n      display: table-header-group;\n    }\n    \n    tr {\n      page-break-inside: avoid;\n    }\n    \n    /* ============================================================\n       HEADER DEL CERTIFICADO\n       ============================================================ */\n    .certificate-header {\n      display: flex;\n      align-items: stretch;\n      gap: 15px;\n      margin-bottom: 20px;  /* ← TICKET-003: Reducido de 25px a 20px */\n    }\n    \n    .header-left {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      width: 140px;\n      background: var(--blue-color);\n      border-radius: 8px;\n      padding: 15px;\n      flex-shrink: 0;\n    }\n    \n    .logo {\n      width: 100px;\n      height: auto;\n    }\n    \n    .header-right {\n      flex: 1;\n      padding: 15px 20px;\n      background: var(--cyan-color);\n      border-radius: 8px;\n      display: flex;\n      flex-direction: column;\n      justify-content: center;\n    }\n    \n    .header-title {\n      position: relative;\n      font-size: 25px;\n      font-weight: 600;\n      padding-bottom: 8px;\n      margin-bottom: 8px;\n      letter-spacing: 0.5px;\n      color: var(--text-black-color);\n    }\n\n    .header-title::after\n    {\n      content: \"\";\n      position: absolute;\n      height: 1px;\n      left: 0;\n      bottom: 0;\n      width: 100%;\n      background-color: var(--border-title-gray-color);  /* Línea flotante sutil */\n    }\n    \n    .header-metadata {\n      font-size: 9pt;\n      display: flex;\n      justify-content: space-between;\n      color: var(--text-black-color);\n    }\n    \n    .metadata-item {\n      display: inline-block;\n    }\n\n    .metadata-item span { font-weight: 500; }\n    \n    .metadata-label {\n      font-weight: 500;\n    }\n    \n    /* ============================================================\n       RESUMEN DEL PROYECTO\n       ============================================================ */\n    .section-title-sin-linea, .section-title {\n      font-size: 16px;\n      font-weight: 900;\n      color: var(--text-black-color);\n      margin-bottom: 12px;  /* ← TICKET-003: Reducido de 15px a 12px */\n      margin-top: 15px;  /* ← TICKET-003: Reducido de 20px a 15px */\n    }\n\n    .resumen-grid {\n      display: flex;\n      flex-direction: column;\n      gap: 0;\n      margin-bottom: 15px;\n      padding: 0 15px;\n      border: 2px solid var(--border-gray-color);\n      border-radius: 12px;\n      overflow: hidden;\n      background: var(--text-white-color);\n    }\n\n    .resumen-item-container {\n      display: flex;\n      flex-direction: row;\n      border-bottom: 1px solid var(--border-gray-color);\n      padding: 15px 0;\n      gap: 10px;\n    }\n\n    .resumen-item-container:last-child {\n      border-bottom: none;\n    }\n    \n    .resumen-item {\n      display: flex;\n      flex: 1;\n      gap: 5px;\n    }\n    \n    .resumen-item:nth-child(1),\n    .resumen-item:nth-child(2) {\n      /* Fila 1: 2 items de 3 columnas */\n      grid-column: span 3;\n    }\n    \n    .resumen-item:nth-child(3),\n    .resumen-item:nth-child(4),\n    .resumen-item:nth-child(5) {\n      /* Fila 2: 3 items de 2 columnas */\n      grid-column: span 2;\n    }\n    \n    .resumen-item:nth-child(6),\n    .resumen-item:nth-child(7) {\n      /* Fila 3: 2 items de 3 columnas */\n      grid-column: span 3;\n      border-bottom: none;\n    }\n    \n    .resumen-label {\n      font-weight: 900;\n      color: var(--text-gray-color);\n      white-space: nowrap;\n    }\n    \n    .resumen-value {\n      color: var(--text-gray-color);\n    }\n    \n    /* ============================================================\n       DISCLAIMER/IMPORTANTE\n       ============================================================ */\n    .disclaimer {\n      \n      border: 1px solid var(--blue-color);\n      border-radius: 12px;\n      padding: 12px;  /* ← TICKET-003: Reducido de 15px a 12px */\n      padding-right: 40px;\n      margin: 15px 0;  /* ← TICKET-003: Reducido de 20px a 15px */\n    }\n    \n    .disclaimer-title {\n      font-size: 12pt;\n      font-weight: 900;\n    }\n    \n    .disclaimer-text {\n      font-size: 9.5pt;\n      line-height: 1.4;  /* ← TICKET-003: Reducido de 1.6 a 1.4 */\n      color: var(--text-black-color);\n    }\n    /* ============================================================\n       TABLAS DE HONORARIOS\n       ============================================================ */\n    table {\n      border-collapse: separate;\n      border-spacing: 0;\n      margin-bottom: 15px;  /* ← TICKET-003: Reducido de 20px a 15px */\n      padding: 0 15px;  /* Padding horizontal para efecto de líneas flotantes */\n      font-size: 10pt;  /* ← TICKET-003: Reducido de 9pt a 8.5pt */\n      background: var(--text-white-color);\n      border: 2px solid var(--border-gray-color);\n      border-radius: 12px;\n      overflow: hidden;\n\n      table-layout: fixed;\n\n      margin-right: 1px;\n    }\n\n    table:last-child {\n      margin-bottom: 0;\n    }\n\n    table, .resumen-grid, .disclaimer\n    {\n      width: calc(100% - 3px);\n    }\n    \n    thead th {\n      font-size: 9pt;\n      padding: 15px 0;  /* ← TICKET-003: Reducido de 10px a 8px */\n      text-align: left;\n      border-bottom: 1px solid var(--border-gray-color);\n      font-weight: 900;\n      color: var(--text-gray-color);\n    }\n    \n    /* Anchos específicos para cada columna (solo tablas de honorarios) */\n    table:not(.etapas-table) thead th:nth-child(1),\n    table:not(.etapas-table) tbody td:nth-child(1) {\n      width: 5%;\n      text-align: left;\n    }\n\n    table:not(.etapas-table) thead th:nth-child(2),\n    table:not(.etapas-table) tbody td:nth-child(2) {\n      width: 45%;\n    }\n    \n    table:not(.etapas-table) thead th:nth-child(3),\n    table:not(.etapas-table) tbody td:nth-child(3) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table:not(.etapas-table) thead th:nth-child(4),\n    table:not(.etapas-table) tbody td:nth-child(4) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table:not(.etapas-table) thead th:nth-child(5),\n    table:not(.etapas-table) tbody td:nth-child(5) {\n      width: 20%;\n      text-align: left;\n    }\n    \n    \n     /* Anchos específicos para cada columna - Subtotales */\n    table tr.subtotal-row td:nth-child(1) {\n      width: 50%;\n      text-align: left;\n    }\n\n    table tr.subtotal-row td:nth-child(2) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table tr.subtotal-row td:nth-child(3) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table tr.subtotal-row td:nth-child(4) {\n      width: 20%;\n      text-align: left;\n    }\n\n    /* Anchos específicos para cada columna - Totales */\n    table tr.total-row td:nth-child(1) {\n      width: 50%;\n      text-align: left;\n    }\n\n    table tr.total-row td:nth-child(2) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table tr.total-row td:nth-child(3) {\n      width: 15%;\n      text-align: left;\n    }\n    \n    table tr.total-row td:nth-child(4) {\n      width: 20%;\n      text-align: left;\n    }\n\n    /*\n    thead th:first-child {\n      border-top-left-radius: 12px;\n    }\n    \n    thead th:last-child {\n      border-top-right-radius: 12px;\n    }*/\n    \n    tbody td {\n      padding: 15px 0;  /* ← TICKET-003: Reducido de 8px a 6px */\n      border-bottom: 1px solid var(--border-gray-color);\n    }\n    /*\n    tbody tr:last-child td {\n      border-bottom: none;\n    }*/\n    /*\n    tbody tr:last-child td:first-child {\n      border-bottom-left-radius: 12px;\n    }\n    \n    tbody tr:last-child td:last-child {\n      border-bottom-right-radius: 12px;\n    }*/\n    \n    \n    .centered {\n      text-align: center;\n    }\n    \n    .right-align {\n      text-align: right;\n    }\n    \n    .subtotal-row {\n      \n      color: var(--blue-color);\n      font-weight: 900;\n      \n    }\n    \n    .subtotal-row td {\n      padding: 15px 0;  /* Solo padding vertical para efecto flotante */\n      border-bottom: none;\n    }\n    \n    .subtotal-row td:first-child {\n      text-align: left !important;\n      border-bottom-left-radius: 12px;\n    }\n    \n    .subtotal-row td:last-child {\n      text-align: left !important;\n      border-bottom-right-radius: 12px;\n    }\n    \n    .totales-table\n    {\n      border: 2px solid var(--blue-color);\n    }\n\n    .total-row {\n      color: var(--blue-color);\n      font-weight: 900;\n      font-size: 10pt;\n      /*border-bottom: 1px solid var(--blue-color);*/\n    }\n    \n    .total-row:last-child{\n      color: var(--text-black-color);\n    }\n    \n    .total-row td {\n      padding: 12px 0;  /* Solo padding vertical para efecto flotante */\n      border-bottom: 1px solid var(--blue-color);\n    }\n\n    .total-row:last-child td {\n      border-bottom: none;\n    }\n    \n    .total-row td:first-child {\n      text-align: left !important;\n      \n    }\n    \n    .total-row td:last-child {\n      \n      text-align: left !important;\n    }\n    \n    /* Separaci&oacute;n entre secciones de tablas */\n    .table-section {\n      margin-bottom: 10px;\n    }\n    \n    /* ============================================================\n       NOTA FINAL\n       ============================================================ */\n     .nota-final {\n      padding: 0 10px;\n      \n      font-size: 9pt;\n    }\n    \n    /* ============================================================\n       PaGINA 2 - NOTAS\n       ============================================================ */\n    .notas-section {\n      margin-top: 1px;\n    }\n        \n    .nota-block h4 {\n      font-size: 14px;\n      line-height: 1.4;  /* ← TICKET-003: Reducido de 1.6 a 1.4 */\n      font-weight: 900;\n      margin-top: 5px;\n      \n      /* margin-bottom: 8px; */\n    }\n    \n    .nota-block p {\n      font-size: 9.2pt;\n      line-height: 1.2;  /* ← TICKET-003: Reducido de 1.6 a 1.4 */\n      text-align: justify;\n    }\n    \n    .etapas-table {\n      width: auto;\n      min-width: 250px;\n      margin: 10px 0;\n      padding: 0 15px;  /* Padding horizontal para efecto de líneas flotantes */\n      border-collapse: collapse;\n      font-size: 9.2pt;\n      border: none;\n      border-radius: 0;\n    }\n    \n    .etapas-table td {\n      padding: 6px 0;  /* Solo padding vertical para efecto flotante */\n      border-bottom: 1px solid var(--border-gray-color);\n    }\n    .etapas-table tr:last-child td {\n      border-bottom: none;\n    }\n    \n  </style>\n</head>\n<body>\n  <!-- ========================================\n       PaGINA 1: DATOS DEL C&aacute;LCULO\n       ======================================== -->\n  <div class=\"page\">\n    <!-- Header del Certificado -->\n    <div class=\"certificate-header\">\n      <div class=\"header-left\">\n        <img src=\"{{logoCPAU}}\" alt=\"CPAU Logo\" class=\"logo\" />\n      </div>\n      <div class=\"header-right\">\n        <div class=\"header-title\">C&aacute;lculo de honorarios profesionales sugeridos</div>\n        <div class=\"header-metadata\">\n          <div class=\"metadata-item\">\n            <span class=\"metadata-label\">Tipo:</span>\n            <span>{{tipoNombre}}</span>\n          </div>\n          <div class=\"metadata-item\">\n            <span class=\"metadata-label\">Fecha:</span>\n            <span>{{currentDate}}</span>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Disclaimer Legal -->\n    <div class=\"disclaimer-container\">\n      <p class=\"disclaimer-text\">\n        Este c&aacute;lculo es una <strong>estimaci&oacute;n de referencia</strong> basada en los datos proporcionados \n        y factores est&aacute;ndar del mercado. Los valores finales pueden variar seg&uacute;n condiciones particulares \n        de cada proyecto. <strong>No constituye una cotizaci&oacute;n formal ni un compromiso contractual.</strong>\n        <br />\n        <br />\n        {{{vigenciaFE}}}\n        </p>\n    </div>\n\n\n    <!-- Resumen del Proyecto -->\n    <h4 class=\"section-title\">Resumen del Proyecto - Informaci&oacute;n ingresada por el/la profesional</h4>\n    <div class=\"resumen-grid\">\n      <!-- Fila 1: Nombre del Proyecto | Comitente -->\n      <div class=\"resumen-item-container\">\n\n        <div class=\"resumen-item\">\n          <span class=\"resumen-label\">Nombre del Proyecto:</span>\n          <span class=\"resumen-value\">{{nombreProyecto}}</span>\n        </div>\n        <div class=\"resumen-item\">\n          <span class=\"resumen-label\">Comitente:</span>\n          <span class=\"resumen-value\">{{cliente}}</span>\n        </div>\n       \n      </div>\n    </div>\n\n    <!-- Detalle de Honorarios -->\n    <h4 class=\"section-title-sin-linea\">Detalle de honorarios</h4>\n\n    <!-- SECCIoN: Honorarios Especialidades -->\n    {{#if honorariosEspecialidades}}\n    <div class=\"table-section\">\n      <table>\n        <!-- Encabezado: solo si NO existe honorariosObra NI honorariosAdicionales -->\n        {{#unless honorariosObra}}\n          {{#unless honorariosAdicionales}}\n          <thead>\n            <tr>\n              <th class=\"centered\">&Iacute;tem</th>\n              <th>Tarea Profesional</th>\n              <th class=\"right-align\">Importe ARS</th>\n            </tr>\n          </thead>\n          {{/unless}}\n        {{/unless}}\n        <tbody>\n          {{#each honorariosEspecialidades}}\n          <tr>\n            <td class=\"centered\">{{this.indice}}</td>\n            <td>\n              {{this.tareaProfesional}}\n            </td>\n            <td class=\"right-align\">{{this.importeARS}}</td>\n          </tr>\n          {{/each}}\n          \n          <!-- Subtotal Especialidades -->\n          <!-- <tr class=\"subtotal-row\">\n            <td colspan=\"2\"><strong>Total honorarios especialidades</strong></td>\n            <td class=\"right-align\"><strong>{{subtotalEspecialidadesARS}}</strong></td>\n          </tr> -->\n        </tbody>\n      </table>\n    </div>\n    {{/if}}\n\n    <!-- TOTAL GENERAL -->\n    <div class=\"table-section\">\n      <table class=\"totales-table\">\n        <tbody>\n          <tr class=\"total-row\">\n            <td colspan=\"2\"><strong>TOTAL HONORARIOS</strong></td>\n            <td class=\"right-align\"><strong>{{subtotalEspecialidadesARS}}</strong></td>\n          </tr>\n          <!-- <tr class=\"total-row\">\n            <td colspan=\"3\"><strong>Plazo estimado de ejecuci&oacute;n: {{plazoEjecucion}} meses</strong></td>\n            <td class=\"right-align\"></td>\n            <td class=\"centered\"></td>\n          </tr> -->\n        </tbody>\n      </table>\n    </div>\n\n    <!-- Nota Final -->\n    <div class=\"nota-final\">\n      <p>NOTA: Este honorario corresponde &uacute;nicamente a las tareas profesionales seleccionadas. NO incluye IVA.</p>\n    </div>\n  </div>\n  <!-- Fin pagina 1 -->\n\n  <!-- ========================================\n       PÁGINA 2: NOTAS\n       ======================================== -->\n  <div class=\"page\">\n    <!-- Header (repetido para PDF) -->\n    <div class=\"certificate-header\">\n      <div class=\"header-left\">\n        <img src=\"{{logoCPAU}}\" alt=\"CPAU Logo\" class=\"logo\" />\n      </div>\n      <div class=\"header-right\">\n        <div class=\"header-title\">C&aacute;lculo de honorarios profesionales sugeridos</div>\n        <div class=\"header-metadata\">\n          <div class=\"metadata-item\">\n            <span class=\"metadata-label\">Tipo:</span>\n            <span>{{tipoNombre}}</span>\n          </div>\n          <div class=\"metadata-item\">\n            <span class=\"metadata-label\">Fecha:</span>\n            <span>{{currentDate}}</span>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Contenido de Notas -->\n    <div class=\"notas-section\">\n      <h2 class=\"section-title-sin-linea\">Notas</h2>\n      \n      <!-- Alcance y car&aacute;cter del c&aacute;lculo -->\n      <section class=\"nota-block\">\n        <h4>Variables de cálculo</h4>\n        <p>Las expresiones que determinan honorarios están en función de un coeficiente “K” cuyo valor responde a las variaciones mensuales del Índice del Costo de la Construcción (ICC) del INDEC, que publica el CPAU todos los meses y cuya aplicación tiene por objeto preservar el valor del honorario y su carácter alimentario.\n          En aquellas tareas que se calculan en base a monto de obra, el valor por m2 utilizado en el cálculo constituye una estimación consensuada entre profesional y comitente.\n          El CPAU publica mensualmente índices de referencia de costos de construcción, elaborados por distintos organismos y/o medios, disponibles en la web institucional, quedando a criterio del/la profesional y del comitente seleccionar el valor que consideren adecuado. \n        </p>\n      </section>\n\n      <!-- Alcance de los honorarios sugeridos -->\n      <section class=\"nota-block\">\n        <h4>Alcance de los honorarios sugeridos</h4>\n        <p>Los honorarios resultantes de esta calculadora contemplan las tareas profesionales correspondientes a un encargo ordinario, de acuerdo con los alcances definidos por la normativa vigente y usos profesionales, ver MEPAU\n            Se recomienda a los profesionales acompañar la encomienda con el detalle de tareas, la modalidad de prestación y la lista de documentos entregables y etapas de pago a fin de clarificar el alcance del encargo y evitar reclamos innecesarios.\n        </p>\n      </section>\n\n      <!-- Conceptos no incluidos -->\n      <section class=\"nota-block\">\n        <h4>Conceptos no incluidos en los honorarios</h4>\n        <p>IVA, en caso de corresponder.<br />\n          Derechos de construcción y/o cualquier tipo de gravámenes, tasas o derechos.\n          Cualquier otro concepto que no esté expreso en el cálculo.\n        </p>\n      </section>\n\n      <!-- Resolución de los honorarios -->\n      <section class=\"nota-block\">\n        <h4>Resolución de los honorarios</h4>\n        <p>En caso de que alguna de las partes decida no continuar con la totalidad del encargo, deberán abonarse los honorarios de las tareas efectivamente realizadas \n          según lo acordado por las partes, y considerando las etapas de proyecto previamente mencionadas en este documento.</p>\n        <p>En caso de rescisión unilateral por parte del comitente, se deberá convenir un resarcimiento en favor del profesional por las tareas encomendadas y no ejecutadas, \n          de acuerdo a la normativa vigente.</p>\n      <p><br></p>\n      <p><br></p>\n        <p>Para ampliar la información consultar al MEPAU, capítulo 02 Honorarios, o ponerse en contacto con tecnica@cpau.org</p>\n      </section>\n\n    </div>\n  </div>\n\n  <!-- Fin pagina 2 -->\n</body>\n</html>','/* CSS embebido en html_template */','{\"format\": \"A4\", \"margin\": {\"top\": \"20mm\", \"left\": \"15mm\", \"right\": \"15mm\", \"bottom\": \"20mm\"}, \"printBackground\": true, \"preferCSSPageSize\": false}','handlebars','{\"formData\": {\"cliente\": \"string\", \"tipoObra\": \"string\", \"valorObra\": \"number\", \"nombreProyecto\": \"string\", \"superficieCubierta\": \"number\", \"superficieSemicubierta\": \"number\"}, \"currentDate\": \"string\", \"calculationNumber\": \"string\", \"calculationResult\": {\"moneda\": \"string\", \"honorarioTotal\": \"number\"}}','{\"logoCPAU\": \"data:image/svg+xml;base64,\"}','2026-06-18 18:13:29','2026-07-24 12:37:07',1);
/*!40000 ALTER TABLE `Entregables_PDF` ENABLE KEYS */;
UNLOCK TABLES;

