  `orden` tinyint DEFAULT NULL,
  `codi` char(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion_larga` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vigente` tinyint(1) NOT NULL DEFAULT '0',
  `calc_obra_valor_obra_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_num1_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_num2_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_num3_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_num4_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_rel_id1_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_rel_id2_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_bol1_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_bol2_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_bol3_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_bol4_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_bol5_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_str1_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_str2_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calc_valor_str3_des` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `user_id` int DEFAULT NULL,
  `baja_fecha` datetime DEFAULT NULL COMMENT 'Fecha de baja lógica',
  `baja_usuario_id` int DEFAULT NULL COMMENT 'Usuario que realizó la baja',
  PRIMARY KEY (`tarea_id`),
  UNIQUE KEY `codi` (`codi`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `Tareas_Profesionales_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `Usuarios` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
