CREATE DEFINER=`admin`@`%` PROCEDURE `Calcular_Honorario_MEDPLAN`(
  IN p_calculo_id INT
)
bloque_principal: BEGIN
  -- ========================================================================
  -- DECLARACIÓN DE VARIABLES LOCALES
  -- ========================================================================
  
  -- Datos del cálculo
  
  DECLARE v_obra_tipologia VARCHAR(50);
  DECLARE v_descripcion_servicio VARCHAR(200);
  DECLARE v_total_horas DECIMAL(6,2);
  DECLARE v_hasta_60_km BOOLEAN;
  DECLARE v_bol1 BOOLEAN;
  DECLARE v_bol2 BOOLEAN;
  DECLARE v_bol3 BOOLEAN;
  DECLARE v_sup1 DECIMAL(15,2);
  DECLARE v_sup2 DECIMAL(15,2);
  DECLARE v_sup3 DECIMAL(15,2);
  
  declare v_valor_k DECIMAL(15,2);
  DECLARE v_coef_sup_k_a_afec DECIMAL(8,7);
  DECLARE v_coef_k_a_afec DECIMAL(6,5);

  -- Variables de cálculo de ítems
  DECLARE v_item_numero INT DEFAULT 0;
  DECLARE v_importe_item DECIMAL(15,2);
  DECLARE v_descripcion VARCHAR(500);
  DECLARE v_tarea_profesional VARCHAR(200);

  -- Acumulador de totales
  DECLARE v_total_honorarios DECIMAL(15,2);
  DECLARE v_solo_calculo BOOLEAN;



  -- ========================================================================
  -- PASO 1: LEER DATOS DEL CÁLCULO
  -- ========================================================================


  SELECT
      obra_tipologia,
      calc_valor_str1,
      COALESCE(horas, 0),
      hasta_60_km,
      calc_valor_bol1,
      calc_valor_bol2,
      calc_valor_bol3,
      calc_valor_num1,
      calc_valor_num2,
      calc_valor_num3
    INTO
      v_obra_tipologia,
      v_descripcion_servicio,
      v_total_horas,
      v_hasta_60_km,
      v_bol1,
      v_bol2,
      v_bol3,
      v_sup1,
      v_sup2,
      v_sup3
    FROM
      Calculos
    WHERE
      calculo_id = p_calculo_id;

  -- Obtener valorK desde Parámetros
  SELECT
      valor INTO v_valor_k
    FROM
      Parametros
    WHERE
      nombre = 'valorK'
      AND (baja_fecha IS NULL OR baja_fecha > NOW()); -- Solo parámetros activos



  SET v_tarea_profesional = 'Medición y ejecución de Planos Art. 3.21'; 
  IF v_descripcion_servicio IS NULL THEN
    SET v_descripcion_servicio = v_obra_tipologia; -- Si no se especifica descripción, usar la tipología de obra
  END IF;



  -- ========================================================================
  -- PASO 2: CALCULAR HONORARIOS POR TAREA PROFESIONAL
  -- MEDPLAN 
  -- ========================================================================

   
  -- CALCULAR PARA 'MPTER'
  -- Según Artículo 3.21.1 de la Resolución CPAU A115

  SET v_total_honorarios = 0;
  SET v_item_numero = 0;

  IF v_obra_tipologia = 'MPTER' or v_obra_tipologia = 'MPEST' THEN
      -- Lógica específica para MPTER
      -- Art 3.21.1 Terrenos y ejecución de Planos
      -- Art 3.21.3 Estructuras e instalaciones

      SET v_total_honorarios = 0;

      IF v_obra_tipologia = 'MPTER' THEN
        SET v_descripcion = 'Art. 3.21.1 ';
        ELSE
          SET v_descripcion = 'Art. 3.21.3 ';
      END IF;
      

      CALL Calcular_Hon_Art_1_13(
        p_calculo_id,
        v_tarea_profesional,
        v_total_horas, -- Cantidad de horas
        v_hasta_60_km, -- Hasta 60 km
        v_valor_k,
        v_descripcion,
        false,
        v_item_numero,
        v_total_honorarios
      );
     
      IF v_obra_tipologia = 'MPTER' THEN

        -- Agregar el 50% según Art 3.21.1
        SET v_importe_item = v_total_honorarios * 0.50; -- 50% sobre Art. 3.21.1
        SET v_descripcion = 'Adic. según Art. 3.21.1 (50%) sobre Art. 1.13'; 
        SET v_item_numero = v_item_numero + 1;
        CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
        SET v_total_honorarios = v_importe_item; -- Actualizar el total de honorarios

      END IF;


  END IF;


  IF v_obra_tipologia = 'MPCON' THEN
      -- Lógica específica para MPCON
      -- Art 3.21.2 Construcciones y ejecución de Planos


      -- Reutilizar la lógica de cálculo de honorarios para MPCON según Art. 3.21.2
      CALL Calcular_Hon_Art_3_21_2(
        p_calculo_id,
        v_tarea_profesional,
        v_valor_k,
        v_bol1,
        v_bol2,
        v_bol3,
        v_sup1,
        v_sup2,
        v_sup3,
        v_item_numero,
        v_total_honorarios
      );

  END IF;

  -- ========================================================================
  -- PASO 5: ACTUALIZAR METADATA EN MASTER
  -- ========================================================================
  
  UPDATE Calculos SET
    total_honorarios = v_total_honorarios,
    metadata_valor_k = v_valor_k,
    metadata_rango_costo_obra = null,
    metadata_numero_items = v_item_numero
  WHERE calculo_id = p_calculo_id;
  
END bloque_principal ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Calcular_Honorario_PERI` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`admin`@`%` PROCEDURE `Calcular_Honorario_PERI`(
  IN p_calculo_id INT
)
bloque_principal: BEGIN
  -- ========================================================================
  -- DECLARACIÓN DE VARIABLES LOCALES
  -- ========================================================================
  
  -- Datos del cálculo
  DECLARE v_valor_en_juego DECIMAL(15,2);
  DECLARE v_desconoce_valor_en_juego BOOLEAN;
  DECLARE v_cant_horas NUMERIC(10,2);
  DECLARE v_hasta_60_km BOOLEAN;

  DECLARE v_descripcion_servicio VARCHAR(200);
  DECLARE v_coef_k DECIMAL(10,2);
  DECLARE v_coef_K_a_afectar DECIMAL(6,5);
  DECLARE v_coef_V_a_afectar DECIMAL(6,5);

  -- Variables de cálculo de ítems
  DECLARE v_item_numero INT DEFAULT 0;
  DECLARE v_importe_item DECIMAL(15,2);
  DECLARE v_descripcion VARCHAR(500);
  DECLARE v_tarea_profesional VARCHAR(200);

  -- Acumulador de totales
  DECLARE v_total_honorarios DECIMAL(15,2) DEFAULT 0;

  -- Constantes de cálculo (CPAU 2026 - SPEC-CALC-002)
  DECLARE v_valor_k DECIMAL(15,2);
  



  -- ========================================================================
  -- PASO 1: LEER DATOS DEL CÁLCULO
  -- ========================================================================


  SELECT
      COALESCE(calc_valor_num1, 0),
      calc_valor_bol1,
      hasta_60_km,
      COALESCE(horas, 0)
    INTO
      v_valor_en_juego,
      v_desconoce_valor_en_juego,
      v_hasta_60_km,
      v_cant_horas
    FROM
      Calculos
    WHERE
      calculo_id = p_calculo_id;


  SET v_tarea_profesional = 'Peritajes (PERI)'; 
  


  -- Obtener valorK desde Parámetros
  SELECT
      valor INTO v_valor_k
    FROM
      Parametros
    WHERE
      nombre = 'valorK'
      AND (baja_fecha IS NULL OR baja_fecha > NOW()); -- Solo parámetros activos


  -- ========================================================================
  -- PASO 2: CALCULAR HONORARIOS
  -- ========================================================================

  SET v_total_honorarios = 0;
  SET v_item_numero = 0;

  IF v_desconoce_valor_en_juego THEN

      -- Lógica específica para Cálculo de Honorarios de Peritajes cuando NO se conoce el valor en juego
    SET v_descripcion = 'Según Art. 10.7.2 - sin valor en juego definido';

    CALL Calcular_Hon_Art_1_13(
      p_calculo_id,
      v_tarea_profesional,
      v_cant_horas, -- Cantidad de horas
      v_hasta_60_km, -- Hasta 60 km
      v_valor_k,
      v_descripcion,
      false, -- No es solo cálculo, se generan ítems
      v_item_numero,
      v_total_honorarios
    );


  ELSE

    -- Llamar al procedimiento para calcular honorarios según Artículo 10.7 cuando se conoce el valor en juego
    CALL Calcular_Hon_Art_10_7(
      p_calculo_id,
      v_valor_en_juego,
      v_valor_k,
      v_tarea_profesional,
      v_item_numero,
      v_total_honorarios
    );

  END IF;
 
  -- ========================================================================
  -- PASO 5: ACTUALIZAR METADATA EN MASTER
  -- ========================================================================
  
  UPDATE Calculos SET
    total_honorarios = v_total_honorarios,
    metadata_valor_k = 0,
    metadata_rango_costo_obra = null,
    metadata_numero_items = v_item_numero
  WHERE calculo_id = p_calculo_id;
  
END bloque_principal ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Calcular_Honorario_PYDOA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`admin`@`%` PROCEDURE `Calcular_Honorario_PYDOA`(
  IN p_calculo_id INT
)
BEGIN
  -- ========================================================================
  -- DECLARACIÓN DE VARIABLES LOCALES
  -- ========================================================================
  
  -- Datos del cálculo
  DECLARE v_valor_obra DECIMAL(15,2);
  DECLARE v_obra_tipologia VARCHAR(50);
  DECLARE v_tarea_obra_proyecto BOOLEAN;
  DECLARE v_tarea_obra_direccion BOOLEAN;
  DECLARE v_tarea_instalacion_sanitaria BOOLEAN;
  DECLARE v_tarea_instalacion_electrica BOOLEAN;
  DECLARE v_tarea_instalacion_contra_incendio BOOLEAN;
  DECLARE v_tarea_instalacion_termomecanica BOOLEAN;
  DECLARE v_tarea_proyecto_estructuras BOOLEAN;
  DECLARE v_tarea_supervision_obra BOOLEAN;
  DECLARE v_tarea_documentacion_ejecutiva BOOLEAN;
  
  -- Constantes de cálculo (CPAU 2026 - SPEC-CALC-002)
  DECLARE v_valor_k DECIMAL(15,2);
  
  -- Variables de rango
  DECLARE v_coeficiente_k DECIMAL(10,4);
  DECLARE v_rango_final VARCHAR(1);
  DECLARE v_rango_final_numero INT; -- 1=A, 2=B, 3=C, 4=D
  
  -- Límites de rangos en pesos (SPEC-CALC-002)
  DECLARE v_limite_a_sup DECIMAL(15,2);
  DECLARE v_limite_b_inf DECIMAL(15,2);
  DECLARE v_limite_b_sup DECIMAL(15,2);
  DECLARE v_limite_c_inf DECIMAL(15,2);
  DECLARE v_limite_c_sup DECIMAL(15,2);
  DECLARE v_limite_d_inf DECIMAL(15,2);
  
  -- Variables de iteración por rangos
  DECLARE v_rango_actual INT DEFAULT 1;
  DECLARE v_rango_nombre VARCHAR(1);
  DECLARE v_lim_inferior DECIMAL(15,2);
  DECLARE v_lim_superior DECIMAL(15,2);
  DECLARE v_lim_sup_efectivo DECIMAL(15,2);
  DECLARE v_monto_afectado DECIMAL(15,2);
  
  -- Coeficientes según rango
  DECLARE v_coef_obra DECIMAL(6,5);
  DECLARE v_coef_k DECIMAL(6,5);
  DECLARE v_coef_remodelacion DECIMAL(6,5);
  
  -- Variables de cálculo de ítems
  DECLARE v_item_numero INT DEFAULT 0;
  DECLARE v_importe_item DECIMAL(15,2);
  DECLARE v_importe_adicional_remodelacion DECIMAL(15,2);
  DECLARE v_descripcion VARCHAR(500);
  DECLARE v_tarea_profesional VARCHAR(200);
  DECLARE v_porcentaje_tarea DECIMAL(4,2);
  
  DECLARE v_tot_direccion DECIMAL(15,2) DEFAULT 0;
  DECLARE v_tot_proyecto_calculado DECIMAL(15,2) DEFAULT 0;
  DECLARE v_tot_proyecto DECIMAL(15,2) DEFAULT 0;

  -- Acumulador de totales
  DECLARE v_total_honorarios DECIMAL(15,2) DEFAULT 0;
  
  -- ========================================================================
  -- PASO 1: LEER DATOS DEL CÁLCULO
  -- ========================================================================
  
  SELECT 
    obra_valor_obra,
    obra_tipologia,
    tarea_obra_proyecto,
    tarea_obra_direccion,
    tarea_instalacion_sanitaria,
    tarea_instalacion_electrica,
    tarea_instalacion_contra_incendio,
    tarea_instalacion_termomecanica,
    tarea_proyecto_estructuras,
    tarea_supervision_obra,
    tarea_documentacion_ejecutiva
  INTO
    v_valor_obra,
    v_obra_tipologia,
    v_tarea_obra_proyecto,
    v_tarea_obra_direccion,
    v_tarea_instalacion_sanitaria,
    v_tarea_instalacion_electrica,
    v_tarea_instalacion_contra_incendio,
    v_tarea_instalacion_termomecanica,
    v_tarea_proyecto_estructuras,
    v_tarea_supervision_obra,
    v_tarea_documentacion_ejecutiva
  FROM Calculos
  WHERE calculo_id = p_calculo_id;
  
  -- Obtener valorK desde Parámetros
  SELECT
      valor INTO v_valor_k
    FROM
      Parametros
    WHERE
      nombre = 'valorK'
      AND (baja_fecha IS NULL OR baja_fecha > NOW()); -- Solo parámetros activos



  -- ========================================================================
  -- PASO 2: CALCULAR LÍMITES DE RANGOS EN PESOS (SPEC-CALC-002)
  -- ========================================================================
  
  -- Rango A: 0 → 1k
  SET v_limite_a_sup = 1 * v_valor_k;
  
  -- Rango B: 1k → 5k
  SET v_limite_b_inf = v_limite_a_sup;
  SET v_limite_b_sup = 5 * v_valor_k;
  
  -- Rango C: 5k → 25k
  SET v_limite_c_inf = v_limite_b_sup;
  SET v_limite_c_sup = 25 * v_valor_k;
  
  -- Rango D: 25k → ∞
  SET v_limite_d_inf = v_limite_c_sup;
  
  -- ========================================================================
  -- PASO 3: DETERMINAR RANGO FINAL (donde cae la obra)
  -- ========================================================================
  
  SET v_coeficiente_k = v_valor_obra / v_valor_k;
  
  IF v_coeficiente_k < 1 THEN
    SET v_rango_final = 'A';
    SET v_rango_final_numero = 1;
  ELSEIF v_coeficiente_k < 5 THEN
    SET v_rango_final = 'B';
    SET v_rango_final_numero = 2;
  ELSEIF v_coeficiente_k < 25 THEN
    SET v_rango_final = 'C';
    SET v_rango_final_numero = 3;
  ELSE
    SET v_rango_final = 'D';
    SET v_rango_final_numero = 4;
  END IF;
  
  -- ========================================================================
  -- PASO 4: CALCULAR HONORARIOS POR TAREA - SISTEMA PROGRESIVO
  -- ========================================================================
  
  -- -----------------------------------------------------------------------
  -- 4.1 PROYECTO DE OBRA (60% del coeficiente) - CON ARRASTRE PROGRESIVO
  -- SPEC-CALC-003: Arrastre progresivo entre rangos
  -- -----------------------------------------------------------------------
  
  IF v_tarea_obra_proyecto or v_tarea_documentacion_ejecutiva THEN
    SET v_tarea_profesional = 'Proyecto de obra de arquitectura';
    SET v_porcentaje_tarea = 0.60;
    
    -- Bucle progresivo: itera desde Rango A hasta el rango final donde cae la obra
    SET v_rango_actual = 1;
    WHILE v_rango_actual <= v_rango_final_numero DO
      
      -- Obtener coeficientes específicos de este rango
      CASE v_rango_actual
        WHEN 1 THEN -- Rango A
          SET v_rango_nombre = 'A';
          SET v_lim_inferior = 0;
          SET v_lim_superior = v_limite_a_sup;
          SET v_coef_obra = 0.14;
          SET v_coef_k = 0;
          SET v_coef_remodelacion = 0.4;
        WHEN 2 THEN -- Rango B
          SET v_rango_nombre = 'B';
          SET v_lim_inferior = v_limite_b_inf;
          SET v_lim_superior = v_limite_b_sup;
          SET v_coef_obra = 0.095;
          SET v_coef_k = 0.00;
          SET v_coef_remodelacion = 0.3;
        WHEN 3 THEN -- Rango C
          SET v_rango_nombre = 'C';
          SET v_lim_inferior = v_limite_c_inf;
          SET v_lim_superior = v_limite_c_sup;
          SET v_coef_obra = 0.06;
          SET v_coef_k = 0.00;
          SET v_coef_remodelacion = 0.25;
        WHEN 4 THEN -- Rango D
          SET v_rango_nombre = 'D';
          SET v_lim_inferior = v_limite_d_inf;
          SET v_lim_superior = 999999999999.99;
          SET v_coef_obra = 0.025;
          SET v_coef_k = 0.00;
          SET v_coef_remodelacion = 0.2;
      END CASE;
      
      -- Calcular límite superior efectivo (no exceder valor de obra)
      SET v_lim_sup_efectivo = IF(v_valor_obra > v_lim_superior, v_lim_superior, v_valor_obra);
      
      -- Solo procesar si hay monto afectado en este rango
      IF v_lim_sup_efectivo > v_lim_inferior THEN
        SET v_monto_afectado = v_lim_sup_efectivo - v_lim_inferior;
        
        -- Ítem por coeficiente de obra (porción que cae en este rango)
        IF v_coef_obra > 0 THEN
          
          SET v_importe_item = ROUND(v_coef_obra * v_monto_afectado * v_porcentaje_tarea);
          
          IF v_tarea_obra_proyecto THEN
            SET v_item_numero = v_item_numero + 1;
            SET v_descripcion = CONCAT('Rango ', v_rango_nombre, 
                                      ' (coef ', CAST((v_coef_obra * 100) AS CHAR), '%)');

            CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
            
          END IF;
          SET v_total_honorarios = v_total_honorarios + v_importe_item;
        
          -- Adicional por Remodelación (se aplica sobre cada ítem de rango)
          IF v_obra_tipologia = 'Remodelación' THEN
            
            SET v_importe_adicional_remodelacion = ROUND(v_coef_remodelacion * v_importe_item);
            
            IF v_tarea_obra_proyecto THEN
              SET v_item_numero = v_item_numero + 1;
              SET v_descripcion = CONCAT('Adicional por Remodelación Art. 3.18 (coef ', 
                                        CAST((v_coef_remodelacion * 100) AS CHAR), '%)');

              CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, 
                                          v_descripcion, v_importe_adicional_remodelacion);
              
            END IF;

            SET v_total_honorarios = v_total_honorarios + v_importe_adicional_remodelacion;
          END IF;
        END IF;
        
        -- Ítem por coeficiente K (solo en rango final)
        IF v_coef_k > 0 AND v_rango_actual = v_rango_final_numero THEN
          SET v_importe_item = ROUND(v_coef_k * v_valor_k * v_porcentaje_tarea);

          IF v_tarea_obra_proyecto THEN
            SET v_item_numero = v_item_numero + 1;
            SET v_descripcion = CONCAT('Rango ', v_rango_nombre, 
                                        ' (coef K ', CAST((v_coef_k * 100) AS CHAR), '%)');
            CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
          END IF;

          SET v_total_honorarios = v_total_honorarios + v_importe_item;
        END IF;
      END IF;

      
      -- Control de salida del bucle
      IF v_valor_obra <= v_lim_superior THEN
        SET v_rango_actual = v_rango_final_numero + 1; -- Forzar salida
      ELSE
        SET v_rango_actual = v_rango_actual + 1; -- Continuar al siguiente rango
      END IF;
    END WHILE;

    IF v_tarea_documentacion_ejecutiva THEN
      SET v_tot_proyecto_calculado = v_total_honorarios;
    END IF;

    IF NOT v_tarea_obra_proyecto THEN
      SET v_total_honorarios = 0;
    END IF;


  END IF;
  
  -- -----------------------------------------------------------------------
  -- 4.2 DIRECCIÓN DE OBRA (40% del coeficiente) - CON ARRASTRE PROGRESIVO
  -- SPEC-CALC-003: Arrastre progresivo entre rangos
  -- -----------------------------------------------------------------------
  
  IF v_tarea_obra_direccion OR v_tarea_supervision_obra THEN
    SET v_tarea_profesional = 'Dirección de obra de arquitectura';
    SET v_porcentaje_tarea = 0.40;
    
    -- Bucle progresivo: itera desde Rango A hasta el rango final donde cae la obra
    SET v_rango_actual = 1;
    WHILE v_rango_actual <= v_rango_final_numero DO
      
      -- Obtener coeficientes específicos de este rango
      CASE v_rango_actual
        WHEN 1 THEN -- Rango A
          SET v_rango_nombre = 'A';
          SET v_lim_inferior = 0;
          SET v_lim_superior = v_limite_a_sup;
          SET v_coef_obra = 0.14;
          SET v_coef_k = 0;
          SET v_coef_remodelacion = 0.4;
        WHEN 2 THEN -- Rango B
          SET v_rango_nombre = 'B';
          SET v_lim_inferior = v_limite_b_inf;
          SET v_lim_superior = v_limite_b_sup;
          SET v_coef_obra = 0.095;
          SET v_coef_k = 0.00;
          SET v_coef_remodelacion = 0.3;
        WHEN 3 THEN -- Rango C
          SET v_rango_nombre = 'C';
          SET v_lim_inferior = v_limite_c_inf;
          SET v_lim_superior = v_limite_c_sup;
          SET v_coef_obra = 0.06;
          SET v_coef_k = 0.00;
          SET v_coef_remodelacion = 0.25;
        WHEN 4 THEN -- Rango D
          SET v_rango_nombre = 'D';
          SET v_lim_inferior = v_limite_d_inf;
          SET v_lim_superior = 999999999999.99;
          SET v_coef_obra = 0.025;
          SET v_coef_k = 0.00;
          SET v_coef_remodelacion = 0.2;
      END CASE;
      
      -- Calcular límite superior efectivo (no exceder valor de obra)
      SET v_lim_sup_efectivo = IF(v_valor_obra > v_lim_superior, v_lim_superior, v_valor_obra);
      
      -- Solo procesar si hay monto afectado en este rango
      IF v_lim_sup_efectivo > v_lim_inferior THEN
        SET v_monto_afectado = v_lim_sup_efectivo - v_lim_inferior;
        
        -- Ítem por coeficiente de obra (porción que cae en este rango)
        IF v_coef_obra > 0 THEN
          
          SET v_importe_item = ROUND(v_coef_obra * v_monto_afectado * v_porcentaje_tarea);
          
          IF v_tarea_obra_direccion THEN
            SET v_item_numero = v_item_numero + 1;
            SET v_descripcion = CONCAT('Rango ', v_rango_nombre, ' (coef ', CAST((v_coef_obra * 100) AS CHAR), '%)');
            
            CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
            SET v_total_honorarios = v_total_honorarios + v_importe_item;
          END IF;
          
          SET v_tot_direccion = v_tot_direccion + v_importe_item;
          
          
          -- Adicional por Remodelación (se aplica sobre cada ítem de rango)
          IF v_obra_tipologia = 'Remodelación' THEN
            
            SET v_importe_adicional_remodelacion = ROUND(v_coef_remodelacion * v_importe_item);

            IF v_tarea_obra_direccion THEN
              SET v_item_numero = v_item_numero + 1;
              SET v_descripcion = CONCAT('Adicional por Remodelación Art. 3.18 (coef ', 
                                          CAST((v_coef_remodelacion * 100) AS CHAR), '%)');
              
              CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, 
                                          v_descripcion, v_importe_adicional_remodelacion);
              SET v_total_honorarios = v_total_honorarios + v_importe_adicional_remodelacion;
            END IF;

            SET v_tot_direccion = v_tot_direccion + v_importe_adicional_remodelacion;
            
          END IF;
        END IF;
        
        -- Ítem por coeficiente K (solo en rango final)
        IF v_coef_k > 0 AND v_rango_actual = v_rango_final_numero THEN
          
          SET v_importe_item = ROUND(v_coef_k * v_valor_k * v_porcentaje_tarea);


          IF v_tarea_obra_direccion THEN
            SET v_item_numero = v_item_numero + 1;
            SET v_descripcion = CONCAT('Rango ', v_rango_nombre, 
                                        ' (coef K ', CAST((v_coef_k * 100) AS CHAR), '%)');
            
            CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
            SET v_total_honorarios = v_total_honorarios + v_importe_item;
          END IF;

          SET v_tot_direccion = v_tot_direccion + v_importe_item;
          
        END IF;
      END IF;
      
      -- Control de salida del bucle
      IF v_valor_obra <= v_lim_superior THEN
        SET v_rango_actual = v_rango_final_numero + 1; -- Forzar salida
      ELSE
        SET v_rango_actual = v_rango_actual + 1; -- Continuar al siguiente rango
      END IF;
    END WHILE;
  END IF;

  IF v_tarea_supervision_obra THEN

      SET v_tarea_profesional = 'Supervisión de obra';
      SET v_descripcion = CONCAT('Sobre total de Honorarios de Dirección de Obra: ', CAST(v_tot_direccion AS CHAR), ' (25%)');
      SET v_item_numero = v_item_numero + 1;
      SET v_importe_item = ROUND(v_tot_direccion * 0.25);

      CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
      SET v_total_honorarios = v_total_honorarios + v_importe_item;
      SET v_tot_direccion = v_importe_item; -- Para posible uso en Documentación ejecutiva

  END IF;

  
  -- -----------------------------------------------------------------------
  -- 4.3 INSTALACIÓN SANITARIA (100%) - ARRASTRE PROGRESIVO
  -- Coeficientes SPEC-CALC-001 (diferenciados por instalación)
  -- -----------------------------------------------------------------------
  IF v_tarea_instalacion_sanitaria THEN
    SET v_tarea_profesional = 'Proyecto de instalación sanitaria y gas';
    SET v_porcentaje_tarea = 1.0;
    
    SET v_rango_actual = 1;
    WHILE v_rango_actual <= v_rango_final_numero DO
      
      CASE v_rango_actual
        WHEN 1 THEN
          SET v_rango_nombre = 'A';
          SET v_lim_inferior = 0;
          SET v_lim_superior = v_limite_a_sup;
          SET v_coef_obra = 0.0070; 
          SET v_coef_k = 0;
        WHEN 2 THEN
          SET v_rango_nombre = 'B';
          SET v_lim_inferior = v_limite_b_inf;
          SET v_lim_superior = v_limite_b_sup;
          SET v_coef_obra = 0.0018;
          SET v_coef_k = 0;
        WHEN 3 THEN
          SET v_rango_nombre = 'C';
          SET v_lim_inferior = v_limite_c_inf;
          SET v_lim_superior = v_limite_c_sup;
          SET v_coef_obra = 0.0004;
          SET v_coef_k = 0;
        WHEN 4 THEN
          SET v_rango_nombre = 'D';
          SET v_lim_inferior = v_limite_d_inf;
          SET v_lim_superior = 999999999999.99;
          SET v_coef_obra = 0.0002;
          SET v_coef_k = 0;
      END CASE;
      
      SET v_lim_sup_efectivo = IF(v_valor_obra > v_lim_superior, v_lim_superior, v_valor_obra);
      
      IF v_lim_sup_efectivo > v_lim_inferior THEN
        SET v_monto_afectado = v_lim_sup_efectivo - v_lim_inferior;
        
        IF v_coef_obra > 0 THEN
          SET v_item_numero = v_item_numero + 1;
          SET v_importe_item = ROUND(v_coef_obra * v_monto_afectado * v_porcentaje_tarea);
          SET v_descripcion = CONCAT('Rango ', v_rango_nombre, 
                                      ' (coef ', CAST((v_coef_obra * 100) AS CHAR), '%)');
          
          CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
          
          SET v_total_honorarios = v_total_honorarios + v_importe_item;

          SET v_tot_proyecto_calculado = v_tot_proyecto_calculado + v_importe_item;

        END IF;
      END IF;
      
      IF v_valor_obra <= v_lim_superior THEN
        SET v_rango_actual = v_rango_final_numero + 1;
      ELSE
        SET v_rango_actual = v_rango_actual + 1;
      END IF;
    END WHILE;
  END IF;
  
  -- -----------------------------------------------------------------------
  -- 4.4 INSTALACIÓN ELÉCTRICA (100%) - ARRASTRE PROGRESIVO
  -- Coeficientes iguales a Sanitaria (SPEC-CALC-001)
  -- -----------------------------------------------------------------------
  IF v_tarea_instalacion_electrica THEN
    SET v_tarea_profesional = 'Proyecto de instalación eléctrica';
    SET v_porcentaje_tarea = 1.0;
    
    SET v_rango_actual = 1;
    WHILE v_rango_actual <= v_rango_final_numero DO
      
      CASE v_rango_actual
        WHEN 1 THEN
          SET v_rango_nombre = 'A';
          SET v_lim_inferior = 0;
          SET v_lim_superior = v_limite_a_sup;
          SET v_coef_obra = 0.0070;
          SET v_coef_k = 0;
        WHEN 2 THEN
          SET v_rango_nombre = 'B';
          SET v_lim_inferior = v_limite_b_inf;
          SET v_lim_superior = v_limite_b_sup;
          SET v_coef_obra = 0.0018;
          SET v_coef_k = 0;
        WHEN 3 THEN
          SET v_rango_nombre = 'C';
          SET v_lim_inferior = v_limite_c_inf;
          SET v_lim_superior = v_limite_c_sup;
          SET v_coef_obra = 0.0004;
          SET v_coef_k = 0;
        WHEN 4 THEN
          SET v_rango_nombre = 'D';
          SET v_lim_inferior = v_limite_d_inf;
          SET v_lim_superior = 999999999999.99;
          SET v_coef_obra = 0.0002;
          SET v_coef_k = 0;
      END CASE;
      
      SET v_lim_sup_efectivo = IF(v_valor_obra > v_lim_superior, v_lim_superior, v_valor_obra);
      
      IF v_lim_sup_efectivo > v_lim_inferior THEN
        SET v_monto_afectado = v_lim_sup_efectivo - v_lim_inferior;
        
        IF v_coef_obra > 0 THEN
          SET v_item_numero = v_item_numero + 1;
          SET v_importe_item = ROUND(v_coef_obra * v_monto_afectado * v_porcentaje_tarea);
          SET v_descripcion = CONCAT('Rango ', v_rango_nombre, 
                                      ' (coef ', CAST((v_coef_obra * 100) AS CHAR), '%)');
          
          CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
          
          SET v_total_honorarios = v_total_honorarios + v_importe_item;

          SET v_tot_proyecto_calculado = v_tot_proyecto_calculado + v_importe_item;

        END IF;
      END IF;
      
      IF v_valor_obra <= v_lim_superior THEN
        SET v_rango_actual = v_rango_final_numero + 1;
      ELSE
        SET v_rango_actual = v_rango_actual + 1;
      END IF;
    END WHILE;
  END IF;
  
  -- -----------------------------------------------------------------------
  -- 4.5 INSTALACIÓN CONTRA INCENDIO (100%) - ARRASTRE PROGRESIVO
  -- Coeficientes propios (SPEC-CALC-001)
  -- -----------------------------------------------------------------------
  IF v_tarea_instalacion_contra_incendio THEN
    SET v_tarea_profesional = 'Proyecto de instalación contra incendio';
    SET v_porcentaje_tarea = 1.0;
    
    SET v_rango_actual = 1;
    WHILE v_rango_actual <= v_rango_final_numero DO
      
      CASE v_rango_actual
        WHEN 1 THEN
          SET v_rango_nombre = 'A';
          SET v_lim_inferior = 0;
          SET v_lim_superior = v_limite_a_sup;
          SET v_coef_obra = 0.0050; 
          SET v_coef_k = 0;
        WHEN 2 THEN
          SET v_rango_nombre = 'B';
          SET v_lim_inferior = v_limite_b_inf;
          SET v_lim_superior = v_limite_b_sup;
          SET v_coef_obra = 0.0018;
          SET v_coef_k = 0;
        WHEN 3 THEN
          SET v_rango_nombre = 'C';
          SET v_lim_inferior = v_limite_c_inf;
          SET v_lim_superior = v_limite_c_sup;
          SET v_coef_obra = 0.0002;
          SET v_coef_k = 0;
        WHEN 4 THEN
          SET v_rango_nombre = 'D';
          SET v_lim_inferior = v_limite_d_inf;
          SET v_lim_superior = 999999999999.99;
          SET v_coef_obra = 0.0001;
          SET v_coef_k = 0;
      END CASE;
      
      SET v_lim_sup_efectivo = IF(v_valor_obra > v_lim_superior, v_lim_superior, v_valor_obra);
      
      IF v_lim_sup_efectivo > v_lim_inferior THEN
        SET v_monto_afectado = v_lim_sup_efectivo - v_lim_inferior;
        
        IF v_coef_obra > 0 THEN
          SET v_item_numero = v_item_numero + 1;
          SET v_importe_item = ROUND(v_coef_obra * v_monto_afectado * v_porcentaje_tarea);
          SET v_descripcion = CONCAT('Rango ', v_rango_nombre, 
                                      ' (coef ', CAST((v_coef_obra * 100) AS CHAR), '%)');
          
          CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
          
          SET v_total_honorarios = v_total_honorarios + v_importe_item;
          SET v_tot_proyecto_calculado = v_tot_proyecto_calculado + v_importe_item;
        END IF;
      END IF;
      
      IF v_valor_obra <= v_lim_superior THEN
        SET v_rango_actual = v_rango_final_numero + 1;
      ELSE
        SET v_rango_actual = v_rango_actual + 1;
      END IF;
    END WHILE;
  END IF;
  
  -- -----------------------------------------------------------------------
  -- 4.6 INSTALACIÓN TERMOMECÁNICA (100%) - ARRASTRE PROGRESIVO
  -- Coeficientes iguales a Contra Incendio (SPEC-CALC-001)
  -- -----------------------------------------------------------------------
  IF v_tarea_instalacion_termomecanica THEN
    SET v_tarea_profesional = 'Proyecto de instalación termomecánica';
    SET v_porcentaje_tarea = 1.0;
    
    SET v_rango_actual = 1;
    WHILE v_rango_actual <= v_rango_final_numero DO
      
      CASE v_rango_actual
        WHEN 1 THEN
          SET v_rango_nombre = 'A';
          SET v_lim_inferior = 0;
          SET v_lim_superior = v_limite_a_sup;
          SET v_coef_obra = 0.0050;
          SET v_coef_k = 0;
        WHEN 2 THEN
          SET v_rango_nombre = 'B';
          SET v_lim_inferior = v_limite_b_inf;
          SET v_lim_superior = v_limite_b_sup;
          SET v_coef_obra = 0.0018;
          SET v_coef_k = 0;
        WHEN 3 THEN
          SET v_rango_nombre = 'C';
          SET v_lim_inferior = v_limite_c_inf;
          SET v_lim_superior = v_limite_c_sup;
          SET v_coef_obra = 0.0002;
          SET v_coef_k = 0;
        WHEN 4 THEN
          SET v_rango_nombre = 'D';
          SET v_lim_inferior = v_limite_d_inf;
          SET v_lim_superior = 999999999999.99;
          SET v_coef_obra = 0.0001;
          SET v_coef_k = 0;
      END CASE;
      
      SET v_lim_sup_efectivo = IF(v_valor_obra > v_lim_superior, v_lim_superior, v_valor_obra);
      
      IF v_lim_sup_efectivo > v_lim_inferior THEN
        SET v_monto_afectado = v_lim_sup_efectivo - v_lim_inferior;
        
        IF v_coef_obra > 0 THEN
          SET v_item_numero = v_item_numero + 1;
          SET v_importe_item = ROUND(v_coef_obra * v_monto_afectado * v_porcentaje_tarea);
          SET v_descripcion = CONCAT('Rango ', v_rango_nombre, 
                                      ' (coef ', CAST((v_coef_obra * 100) AS CHAR), '%)');
          
          CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
          
          SET v_total_honorarios = v_total_honorarios + v_importe_item;
          SET v_tot_proyecto_calculado = v_tot_proyecto_calculado + v_importe_item;
        END IF;
      END IF;
      
      IF v_valor_obra <= v_lim_superior THEN
        SET v_rango_actual = v_rango_final_numero + 1;
      ELSE
        SET v_rango_actual = v_rango_actual + 1;
      END IF;
    END WHILE;
  END IF;
  
  -- -----------------------------------------------------------------------
  -- 4.7 PROYECTO DE ESTRUCTURAS (100%) - ARRASTRE PROGRESIVO
  -- Coeficientes específicos (SPEC-CALC-001)
  -- -----------------------------------------------------------------------
  IF v_tarea_proyecto_estructuras THEN
    SET v_tarea_profesional = 'Proyecto de estructuras';
    SET v_porcentaje_tarea = 1.0;
    
    SET v_rango_actual = 1;
    WHILE v_rango_actual <= v_rango_final_numero DO
      
      CASE v_rango_actual
        WHEN 1 THEN
          SET v_rango_nombre = 'A';
          SET v_lim_inferior = 0;
          SET v_lim_superior = v_limite_a_sup;
          SET v_coef_obra = 0.0090; 
          SET v_coef_k = 0;
        WHEN 2 THEN
          SET v_rango_nombre = 'B';
          SET v_lim_inferior = v_limite_b_inf;
          SET v_lim_superior = v_limite_b_sup;
          SET v_coef_obra = 0.0020;
          SET v_coef_k = 0;
        WHEN 3 THEN
          SET v_rango_nombre = 'C';
          SET v_lim_inferior = v_limite_c_inf;
          SET v_lim_superior = v_limite_c_sup;
          SET v_coef_obra = 0.0015;
          SET v_coef_k = 0;
        WHEN 4 THEN
          SET v_rango_nombre = 'D';
          SET v_lim_inferior = v_limite_d_inf;
          SET v_lim_superior = 999999999999.99;
          SET v_coef_obra = 0.0008;
          SET v_coef_k = 0;
      END CASE;
      
      SET v_lim_sup_efectivo = IF(v_valor_obra > v_lim_superior, v_lim_superior, v_valor_obra);
      
      IF v_lim_sup_efectivo > v_lim_inferior THEN
        SET v_monto_afectado = v_lim_sup_efectivo - v_lim_inferior;
        
        IF v_coef_obra > 0 THEN
          SET v_item_numero = v_item_numero + 1;
          SET v_importe_item = ROUND(v_coef_obra * v_monto_afectado * v_porcentaje_tarea);
          SET v_descripcion = CONCAT('Rango ', v_rango_nombre, 
                                      ' (coef ', CAST((v_coef_obra * 100) AS CHAR), '%)');
          
          CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
          
          SET v_total_honorarios = v_total_honorarios + v_importe_item;
          SET v_tot_proyecto_calculado = v_tot_proyecto_calculado + v_importe_item;
        END IF;
      END IF;
      
      IF v_valor_obra <= v_lim_superior THEN
        SET v_rango_actual = v_rango_final_numero + 1;
      ELSE
        SET v_rango_actual = v_rango_actual + 1;
      END IF;
    END WHILE;
  END IF;

  IF v_tarea_documentacion_ejecutiva THEN


      IF v_tot_proyecto_calculado > 0 THEN

        SET v_tarea_profesional = 'Documentación ejecutiva';
        SET v_descripcion = CONCAT('Sobre total de Honorarios de Proyecto de Obra: ', CAST(v_tot_proyecto_calculado AS CHAR), ' (20%)');
        SET v_item_numero = v_item_numero + 1;
        SET v_importe_item = ROUND(v_tot_proyecto_calculado * 0.20);

        CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
        SET v_total_honorarios = v_total_honorarios + v_importe_item;

      END IF;

  END IF;
  
  -- ========================================================================
  -- PASO 5: ACTUALIZAR METADATA EN MASTER
  -- ========================================================================
  
  UPDATE Calculos SET
    total_honorarios = v_total_honorarios,
    metadata_rango = v_rango_final,
    metadata_valor_k = v_valor_k,
    metadata_rango_costo_obra = v_coeficiente_k,
    metadata_numero_items = v_item_numero
  WHERE calculo_id = p_calculo_id;
  
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Calcular_Honorario_REPTEC` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`admin`@`%` PROCEDURE `Calcular_Honorario_REPTEC`(
  IN p_calculo_id INT
)
bloque_principal: BEGIN
  -- ========================================================================
  -- DECLARACIÓN DE VARIABLES LOCALES
  -- ========================================================================
  
  -- Datos del cálculo
  DECLARE v_valor_obra DECIMAL(15,2);
-- Contiene el código de tarea profesinal a realizar
-- IEC, POL o RTE
  DECLARE v_obra_tipologia VARCHAR(50);
  DECLARE v_descripcion_servicio VARCHAR(200);
  DECLARE v_oferta_aceptada BOOLEAN;
  
  
  
  -- Constantes de cálculo (CPAU 2026 - SPEC-CALC-002)
  DECLARE v_valor_k DECIMAL(15,2);
  
  -- Variables de rango
  DECLARE v_coeficiente_k DECIMAL(10,4);
      
  -- Coeficientes según rango
  DECLARE v_coef_obra DECIMAL(6,5);
  DECLARE v_coef_k DECIMAL(6,5);
  
  
  -- Variables de cálculo de ítems
  DECLARE v_item_numero INT DEFAULT 0;
  DECLARE v_importe_item DECIMAL(15,2);
  DECLARE v_importe_adicional_remodelacion DECIMAL(15,2);
  DECLARE v_descripcion VARCHAR(500);
  DECLARE v_tarea_profesional VARCHAR(200);
  DECLARE v_porcentaje_tarea DECIMAL(4,2);
  
  -- Acumulador de totales
  DECLARE v_total_honorarios DECIMAL(15,2) DEFAULT 0;
    
  -- ========================================================================
  -- PASO 1: LEER DATOS DEL CÁLCULO
  -- ========================================================================

  SELECT 
    obra_valor_obra,
    obra_tipologia,
    calc_valor_str1,
    tarea_obra_proyecto
  INTO
    v_valor_obra,
    v_obra_tipologia,
    v_descripcion_servicio,
    v_oferta_aceptada
  FROM Calculos
  WHERE calculo_id = p_calculo_id;
  
  -- Obtener valorK desde Parámetros
  SELECT
      valor INTO v_valor_k
    FROM
      Parametros
    WHERE
      nombre = 'valorK'
      AND (baja_fecha IS NULL OR baja_fecha > NOW()); -- Solo parámetros activos

  IF v_descripcion_servicio IS NULL THEN
    SET v_descripcion_servicio = v_obra_tipologia; -- Si no se especifica descripción, usar la tipología de obra
  END IF;



  -- ========================================================================
  -- PASO 2: CALCULAR HONORARIOS POR TAREA PROFESIONAL
  -- IEC Y POL SE CALCULAN CON EL MISMO ALGORITMO PERO SE DISTINGUEN EN LA DESCRIPCIÓN Y TAREA PROFESIONAL
  -- ========================================================================
  -- CALCULAR PARA 'IEC' Y 'POL'
  IF v_obra_tipologia = 'IEC' OR v_obra_tipologia = 'POL' THEN

      -- Lógica específica para (IEC y POL comparten algoritmo)

    -- ========================================================================
      -- PASO 3: DETERMINAR RANGO FINAL (donde cae la obra)
      -- ========================================================================
      
      SET v_coeficiente_k = v_valor_obra / v_valor_k;
      
      IF v_coeficiente_k <= 0.5 THEN
        SET v_coef_obra = 0.056;
        SET v_coef_k = 0;
      ELSEIF v_coeficiente_k <= 5 THEN
        SET v_coef_obra = 0.032;
        SET v_coef_k = 0.012;
      ELSEIF v_coeficiente_k <= 25 THEN
        SET v_coef_obra = 0.024;
        SET v_coef_k = 0.052;
      ELSE
        SET v_coef_obra = 0.016;
        SET v_coef_k = 0.252;
      END IF;


      
      -- Para simplificar, asignamos una tarea profesional genérica para IEC
      SET v_tarea_profesional = CONCAT('Honorarios (', v_obra_tipologia, ') Art. 7.2 (Coef M)');
    
      
      SET v_importe_item = ROUND(v_coef_obra * v_valor_obra);
      SET v_descripcion = CONCAT('Honorarios por servicio de ', v_descripcion_servicio, ' (coef ', CAST((v_coef_obra * 100) AS CHAR), '%)');
      
      -- Si es POL no se graba. Pero se tiene que calcular el total de honorarios para IEC y después afectarlo a coeficientes del Art 7.4
      if v_obra_tipologia = 'IEC' THEN
        SET v_item_numero = v_item_numero + 1;
        CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
      END IF;
      

      SET v_total_honorarios = v_total_honorarios + v_importe_item;

      IF v_coef_k > 0 THEN
		  SET v_tarea_profesional = CONCAT('Honorarios (', v_obra_tipologia, ') Art. 7.2 (Coef K)');
        SET v_importe_item = ROUND(v_coef_k * v_valor_k);
        SET v_descripcion = CONCAT('Adicional por valor K (coef ', CAST((v_coef_k * 100) AS CHAR), '%)');
        
        if v_obra_tipologia = 'IEC' THEN
          SET v_item_numero = v_item_numero + 1;
          CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
        END IF;
        
        SET v_total_honorarios = v_total_honorarios + v_importe_item;
      END IF;


    
  END IF;


  -- CALCULAR PARA 'POL'
  IF v_obra_tipologia = 'POL' THEN

    -- Aquí se calcularán los honorarios específicos para POL, que resultan de afectar coeficientes a lo calculado para IEC.
         
    IF not v_oferta_aceptada THEN
      -- Para simplificar, asignamos una tarea profesional genérica para POL
      SET v_tarea_profesional = CONCAT('Oferta no adjudicada Art. 7.4');
    
      SET v_coef_obra = 0.05;
      SET v_importe_item = ROUND(v_total_honorarios * v_coef_obra);
      SET v_descripcion = CONCAT('Honorarios Art. 7.4 (Coef 5% de honorarios Art. 7.2)');

      ELSE

        SET v_tarea_profesional = CONCAT('Designación otro profesional Art. 7.4');
      
        SET v_coef_obra = 0.25;
        SET v_importe_item = ROUND(v_total_honorarios * v_coef_obra);
        SET v_descripcion = CONCAT('Honorarios Art. 7.4 (Coef 25% de honorarios Art. 7.2)');

    END IF;
      
    SET v_item_numero = v_item_numero + 1;
    CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);

    SET v_total_honorarios = v_total_honorarios + v_importe_item;
     
    
  END IF;


-- CALCULAR PARA 'RTE'
  IF v_obra_tipologia = 'RTE' THEN

      -- Lógica específica para RTE

    -- ========================================================================
      -- PASO 3: DETERMINAR RANGO FINAL (donde cae la obra)
      -- ========================================================================
      
      SET v_coeficiente_k = v_valor_obra / v_valor_k;
      
      IF v_coeficiente_k <= 10 THEN
        SET v_coef_obra = 0.0004;
      ELSEIF v_coeficiente_k <= 20 THEN
        SET v_coef_obra = 0.0008;
      ELSEIF v_coeficiente_k <= 60 THEN
        SET v_coef_obra = 0.0012;
      ELSE
        SET v_coef_obra = 0.0016;
      END IF;
      
      SET v_tarea_profesional = CONCAT('Honorario Mensual (', v_obra_tipologia, ') Art. 7.3');
      
      SET v_importe_item = ROUND(v_coef_obra * v_valor_obra);
      SET v_descripcion = CONCAT('Honorarios por servicio de ', v_descripcion_servicio, ' (coef ', CAST((v_coef_obra * 100) AS CHAR), '%)');
      
      SET v_item_numero = v_item_numero + 1;
      CALL Calculos_Items_Grabar(p_calculo_id, v_item_numero, v_tarea_profesional, v_descripcion, v_importe_item);
      SET v_total_honorarios = v_total_honorarios + v_importe_item;
  END IF;

  
  
  -- ========================================================================
  -- PASO 5: ACTUALIZAR METADATA EN MASTER
  -- ========================================================================
  
  UPDATE Calculos SET
    total_honorarios = v_total_honorarios,
    metadata_valor_k = v_valor_k,
    metadata_rango_costo_obra = v_coeficiente_k,
    metadata_numero_items = v_item_numero
  WHERE calculo_id = p_calculo_id;
  
END bloque_principal ;;
DELIMITER ;
