/*!50003 DROP PROCEDURE IF EXISTS `Tareas_Profesionales_Entregables_Grabar` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`admin`@`%` PROCEDURE `Tareas_Profesionales_Entregables_Grabar`(
  IN p_taen_id INT,
  IN p_tarea_id INT,
  IN p_entregable_id INT,
  IN p_orden INT,
  IN p_user_id INT
)
BEGIN

  IF  p_taen_id IS NULL THEN
	BEGIN
		-- Insertar un nuevo registro
		INSERT INTO Tareas_Profesionales_Entregables_PDF (tarea_id, entregable_id, orden, user_id)
		VALUES (p_tarea_id, p_entregable_id, p_orden, p_user_id);
        
		set p_taen_id := LAST_INSERT_ID();
        
	END;
    
  ELSE

    -- Actualizar el registro existente
    UPDATE Tareas_Profesionales_Entregables_PDF
      SET
        tarea_id = p_tarea_id,
        entregable_id = p_entregable_id,
        orden = p_orden,
        updated_at = CURRENT_TIMESTAMP,
        user_id = p_user_id,
        baja_fecha = NULL
      WHERE
        taen_id = p_taen_id;
  END IF;

  select p_taen_id as taen_id;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
